content.arguments:
{"file_path": "C:\work\aholo-docs\fetch-docs.mjs", "content": "import fs from "node:fs";
import path from "node:path";

const OUT = path.dirname(new URL(import.meta.url).pathname).replace(/^\/([A-Za-z]:)/, "$1");

const targets = [
  ["intro", "https://labs.aholo3d.cn/api-docs/"],
  ["intro-en", "https://labs.aholo3d.cn/api-docs/en/intro"],
  ["quickstart", "https://labs.aholo3d.cn/api-docs/quickstart"],
  ["llms.txt", "https://labs.aholo3d.cn/api-docs/llms.txt"],
  ["skill-lux3d", "https://labs.aholo3d.cn/api-docs/en/skills/lux3d"],
  ["sdk-python", "https://labs.aholo3d.cn/api-docs/en/sdk/python"],
  ["sdk-ts", "https://labs.aholo3d.cn/api-docs/en/sdk/typescript"],
  ["sdk-overview", "https://labs.aholo3d.cn/api-docs/en/sdk"],
  ["release-notes", "https://labs.aholo3d.cn/api-docs/en/release-notes"],
  ["mcp", "https://labs.aholo3d.cn/api-docs/en/mcp"],
  ["openapi-yaml", "https://labs.aholo3d.cn/api-docs/openapi.yaml"],
  ["openapi-en-yaml", "https://labs.aholo3d.cn/api-docs/openapi.en.yaml"],
  ["lux3d-api-page", "https://lux3d.aholo3d.cn/lux3d/doc?lang=en_US"],
];

function htmlToText(html) {
  return html
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, " ")
    .replace(/<\/(p|div|li|tr|h[1-6]|pre|table|section)>/gi, "\n")
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<td[^>]*>/gi, " | ")
    .replace(/<[^>]+>/g, "")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#x27;|&#39;/g, "'")
    .replace(/&mdash;/g, "—")
    .replace(/&[a-z]+;/g, " ")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

for (const [name, url] of targets) {
  try {
    const r = await fetch(url, { headers: { "user-agent": "Mozilla/5.0" } });
    const body = await r.text();
    const isText = /\.(txt|yaml|yml)$/.test(url) || body.trimStart().startsWith("---");
    const out = isText ? body : htmlToText(body);
    fs.writeFileSync(path.join(OUT, name + (isText ? ".txt" : ".md")), out, "utf8");
    console.log(`OK  ${name.padEnd(18)} ${String(r.status).padEnd(4)} ${isText ? "raw" : "text"} ${out.length}`);
  } catch (e) {
    console.log(`ERR ${name.padEnd(18)} ${e.message}`);
  }
}
"}

