  ["GET", "/lux3d/v1/generate/task/get?taskid=1"],
  ["POST", "/lux3d/v1/generate/task/list"],
];
for (const [m, p] of tests) {
  try {
    const r = await fetch(BASE + p, {
      method: m,
      headers: { authorization: KEY, "content-type": "application/json" },
      body: m === "POST" ? JSON.stringify({ pageNum: 1, pageSize: 5 }) : undefined,
    });
    const t = await r.text();
    console.log(m + " " + p + " -> " + r.status + " :: " + t.slice(0, 400));
  } catch (e) { console.log(m + " " + p + " -> ERR " + e.message); }
}
'@
