export type EventKind = "think" | "plan" | "tool" | "observe" | "error" | "answer";

export interface AgentEvent {
  id: string;
  /** 相对开始时间，毫秒 */
  t: number;
  kind: EventKind;
  station: StationId;
  title: string;
  detail?: string;
  /** 工具名，例如 lux3d.text_to_3d */
  tool?: string;
  tokens?: number;
  ms?: number;
}

export interface StationMeta {
  name: string;
  en: string;
  /** 角度（度），在 XZ 平面上从 +X 转向 +Z */
  angle: number;
  radius: number;
  /** 道具底部高度 */
  y: number;
  desc: string;
}

export const STATIONS: Record<StationId, StationMeta> = {
  perceive: { name: "感知", en: "PERCEIVE", angle: 90, radius: 4.3, y: 0.2, desc: "看输入" },
  retrieve: { name: "检索", en: "RETRIEVE", angle: 162, radius: 4.3, y: 0.2, desc: "找信息" },
  act: { name: "行动", en: "ACT", angle: 234, radius: 4.3, y: 0.2, desc: "造东西" },
  verify: { name: "校验", en: "VERIFY", angle: 306, radius: 4.3, y: 0.2, desc: "把质量" },
  answer: { name: "交付", en: "DELIVER", angle: 18, radius: 4.3, y: 0.2, desc: "交出去" },
  reason: { name: "推理", en: "REASON", angle: 0, radius: 0, y: 0, desc: "想明白" },
};

export const RING_STATIONS: StationId[] = ["perceive", "retrieve", "act", "verify", "answer"];

export function stationPosition(id: StationId): [number, number, number] {
  const m = STATIONS[id];
  if (id === "reason") return [0, 1.15, 0];
  const rad = (m.angle * Math.PI) / 180;
  return [Math.cos(rad) * m.radius, m.y + 0.9, Math.sin(rad) * m.radius];
}
