{"content": "import * as THREE from "three";
import type { StationId } from "./types";

export const MAX_MOTES = 48;
export const MAX_SPARKS = 1600;

export interface Mote {
  from: THREE.Vector3;
  to: THREE.Vector3;
  ctrl: THREE.Vector3;
  t: number;
  dur: number;
  color: THREE.Color;
  trailAcc: number;
}

export interface Spark {
  p: THREE.Vector3;
  v: THREE.Vector3;
  life: number;
  max: number;
  size: number;
  color: THREE.Color;
  grav: number;
  drag: number;
}

const tmp = new THREE.Vector3();

class Fx {
  motes: Mote[] = [];
  sparks: Spark[] = [];

  travel(from: THREE.Vector3, to: THREE.Vector3, color: string | THREE.Color, dur = 1.0) {
    if (this.motes.length >= MAX_MOTES) this.motes.shift();
    const lift = 1.35 + from.distanceTo(to) * 0.1;
    const mid = from.clone().add(to).multiplyScalar(0.5);
    // 弧线朝向外侧上方，避免穿过中央水晶
    const outward = mid.clone().setY(0);
    if (outward.lengthSq() < 0.01) outward.set(0, 0, 1);
    outward.normalize().multiplyScalar(1.1);
    mid.add(outward).setY(mid.y + lift);

    this.motes.push({
      from: from.clone(),
      to: to.clone(),
      ctrl: mid,
      t: 0,
      dur,
      color: new THREE.Color(color),
      trailAcc: 0,
    });
  }

  burst(pos: THREE.Vector3, color: string | THREE.Color, count = 26, power = 3.6) {
    const c = new THREE.Color(color);
    for (let i = 0; i < count; i++) {
      if (this.sparks.length >= MAX_SPARKS) break;
      const dir = new THREE.Vector3(
        Math.random() * 2 - 1,
        Math.random() * 1.6 - 0.25,
        Math.random() * 2 - 1,
      ).normalize();
      const speed = power * (0.35 + Math.random() * 0.9);
      this.sparks.push({
        p: pos.clone(),
        v: dir.multiplyScalar(speed),
        life: 0.5 + Math.random() * 0.9,
        max: 1.4,
        size: 0.5 + Math.random() * 0.9,
        color: c.clone().offsetHSL((Math.random() - 0.5) * 0.06, 0, (Math.random() - 0.5) * 0.18),
        grav: 2.6,
        drag: 1.7,
      });
    }
  }

  /** 环形冲击波：把粒子压在一个绕 Y 轴旋转的圆盘上射出 */
  shock(pos: THREE.Vector3, color: string | THREE.Color, count = 60, power = 5.2) {
    const c = new THREE.Color(color);
    for (let i = 0; i < count; i++) {
      if (this.sparks.length >= MAX_SPARKS) break;
      const a = (i / count) * Math.PI * 2;
      this.sparks.push({
        p: pos.clone(),
        v: new THREE.Vector3(Math.cos(a), 0.14, Math.sin(a)).multiplyScalar(power * (0.8 + Math.random() * 0.5)),
        life: 0.9 + Math.random() * 0.5,
        max: 1.4,
        size: 0.7 + Math.random() * 0.5,
        color: c.clone(),
        grav: 0.6,
        drag: 1.15,
      });
    }
  }

  private spark(pos: THREE.Vector3, v: THREE.Vector3, color: THREE.Color, life: number, size: number) {
    if (this.sparks.length >= MAX_SPARKS) return;
    this.sparks.push({
      p: pos.clone(),
      v: v.clone(),
      life,
      max: 1.2,
      size,
      color: color.clone(),
      grav: 0.5,
      drag: 2.4,
    });
  }

  positionAt(m: Mote, out: THREE.Vector3) {
    const t = m.t;
    const it = 1 - t;
    out.set(
      it * it * m.from.x + 2 * it * t * m.ctrl.x + t * t * m.to.x,
      it * it * m.from.y + 2 * it * t * m.ctrl.y + t * t * m.to.y,
      it * it * m.from.z + 2 * it * t * m.ctrl.z + t * t * m.to.z,
    );
    return out;
  }

  update(dt: number, onArrive?: (m: Mote) => void) {
    for (let i = this.motes.length - 1; i >= 0; i--) {
      const m = this.motes[i];
      m.t += dt / m.dur;
      if (m.t >= 1) {
        this.motes.splice(i, 1);
        onArrive?.(m);
        continue;
      }
      this.positionAt(m, tmp);
      m.trailAcc += dt;
      if (m.trailAcc > 0.018) {
        m.trailAcc = 0;
        this.spark(
          tmp,
          new THREE.Vector3((Math.random() - 0.5) * 0.35, (Math.random() - 0.5) * 0.35 + 0.2, (Math.random() - 0.5) * 0.35),
          m.color,
          0.4 + Math.random() * 0.3,
          0.35 + Math.random() * 0.3,
        );
      }
    }

    for (let i = this.sparks.length - 1; i >= 0; i--) {
      const s = this.sparks[i];
      s.life -= dt;
      if (s.life <= 0) {
        this.sparks.splice(i, 1);
        continue;
      }
      s.v.y -= s.grav * dt;
      s.v.multiplyScalar(Math.max(0, 1 - s.drag * dt));
      s.p.addScaledVector(s.v, dt);
    }
  }

  reset() {
    this.motes.length = 0;
    this.sparks.length = 0;
  }
}

export const fx = new Fx();

// ---------------------------------------------------------------- 工位脉冲

const lastPulse: Partial<Record<StationId, number>> = {};

export function pulse(id: StationId) {
  lastPulse[id] = performance.now();
}

export function energy(id: StationId): number {
  const t = lastPulse[id];
  if (t === undefined) return 0;
  const dt = (performance.now() - t) / 1000;
  if (dt < 0 || dt > 8) return 0;
  return Math.exp(-dt * 1.25);
}

export function sincePulse(id: StationId): number {
  const t = lastPulse[id];
  if (t === undefined) return 99;
  return (performance.now() - t) / 1000;
}

export function resetPulses() {
  for (const k of Object.keys(lastPulse)) delete lastPulse[k as StationId];
}
