{"content": "import { create } from "zustand";
import { DEMO_TRACE, TRACE_TOTAL } from "./trace";
import type { AgentEvent, StationId } from "./types";

function indexAt(trace: AgentEvent[], t: number): number {
  let idx = -1;
  for (let i = 0; i < trace.length; i++) {
    if (trace[i].t <= t) idx = i;
    else break;
  }
  return idx;
}

interface MindState {
  trace: AgentEvent[];
  totalMs: number;
  playhead: number;
  playing: boolean;
  speed: number;
  activeIndex: number;
  seq: number;
  focus: StationId;
  viewMode: "cinematic" | "orbit";
  liveConnected: boolean;

  play: () => void;
  pause: () => void;
  toggle: () => void;
  seek: (ms: number) => void;
  setSpeed: (s: number) => void;
  setViewMode: (v: "cinematic" | "orbit") => void;
  tick: (dtMs: number) => void;
  reset: () => void;
  setLive: (v: boolean) => void;
}

export const useMind = create<MindState>((set, get) => ({
  trace: DEMO_TRACE,
  totalMs: TRACE_TOTAL,
  playhead: 0,
  playing: true,
  speed: 1,
  activeIndex: -1,
  seq: 0,
  focus: "reason",
  viewMode: "cinematic",
  liveConnected: false,

  play: () => set({ playing: true }),
  pause: () => set({ playing: false }),
  toggle: () => set((s) => ({ playing: !s.playing })),

  seek: (ms) => {
    const { trace, totalMs } = get();
    const clamped = Math.max(0, Math.min(totalMs, ms));
    const idx = indexAt(trace, clamped);
    const focus = idx >= 0 ? trace[idx].station : "reason";
    set((s) => ({
      playhead: clamped,
      activeIndex: idx,
      focus,
      seq: s.seq + 1,
    }));
  },

  setSpeed: (speed) => set({ speed }),
  setViewMode: (viewMode) => set({ viewMode }),
  setLive: (liveConnected) => set({ liveConnected }),

  tick: (dtMs) => {
    const s = get();
    if (!s.playing) return;
    let next = s.playhead + dtMs * s.speed;
    let playing = s.playing;
    if (next >= s.totalMs) {
      next = s.totalMs;
      playing = false;
    }
    const idx = indexAt(s.trace, next);
    const focus = idx >= 0 ? s.trace[idx].station : "reason";
    if (idx !== s.activeIndex) {
      set({ playhead: next, playing, activeIndex: idx, focus, seq: s.seq + 1 });
    } else {
      set({ playhead: next, playing });
    }
  },

  reset: () =>
    set((s) => ({
      playhead: 0,
      activeIndex: -1,
      focus: "reason",
      playing: true,
      seq: s.seq + 1,
    })),
}));

/** 供 r3f 每帧读取，避免订阅开销 */
export const mind = () => useMind.getState();
