{"content": "import * as THREE from "three";

const cache = new Map<string, THREE.Texture>();

/** 生成一张径向渐变贴图（程序化，不依赖任何外部资源） */
export function radialTexture(
  size = 256,
  stops: Array<[number, string]> = [
    [0, "rgba(255,255,255,1)"],
    [1, "rgba(255,255,255,0)"],
  ],
): THREE.Texture {
  const key = size + JSON.stringify(stops);
  const hit = cache.get(key);
  if (hit) return hit;

  const c = document.createElement("canvas");
  c.width = c.height = size;
  const ctx = c.getContext("2d")!;
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  for (const [o, col] of stops) g.addColorStop(o, col);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);

  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  cache.set(key, tex);
  return tex;
}

/** 圆点 sprite，用于粒子 */
export function dotTexture(): THREE.Texture {
  return radialTexture(64, [
    [0, "rgba(255,255,255,1)"],
    [0.35, "rgba(255,255,255,0.85)"],
    [1, "rgba(255,255,255,0)"],
  ]);
}

export function polar(angleDeg: number, radius: number): [number, number] {
  const r = (angleDeg * Math.PI) / 180;
  return [Math.cos(r) * radius, Math.sin(r) * radius];
}
