{"content": "import { useMemo, useRef } from "react";
import * as THREE from "three";
import { useFrame } from "@react-three/fiber";
import { STATIONS, RING_STATIONS } from "../engine/types";
import { polar, radialTexture } from "./util";

const DARK = "#0a0d15";
const PLATE = "#0d1322";

export function Platform() {
  const halo = useMemo(() => radialTexture(256, [
    [0, "rgba(60,200,255,0.30)"],
    [0.55, "rgba(40,120,255,0.10)"],
    [1, "rgba(0,0,0,0)"],
  ]), []);

  const ringMat = useRef<THREE.MeshStandardMaterial>(null!);
  useFrame((s) => {
    if (ringMat.current) {
      ringMat.current.emissiveIntensity = 0.55 + Math.sin(s.clock.elapsedTime * 0.8) * 0.18;
    }
  });

  const spokes = useMemo(
    () =>
      RING_STATIONS.map((id) => {
        const [x, z] = polar(STATIONS[id].angle, 2.55);
        return { id, x, z, rot: Math.PI / 2 - (STATIONS[id].angle * Math.PI) / 180 };
      }),
    [],
  );

  return (
    <group>
      {/* 主体八边形基座 */}
      <mesh position={[0, -0.38, 0]} castShadow receiveShadow>
        <cylinderGeometry args={[6.6, 6.92, 0.76, 8]} />
        <meshStandardMaterial color={DARK} metalness={0.92} roughness={0.38} />
      </mesh>

      {/* 顶面 */}
      <mesh position={[0, 0.005, 0]} rotation={[-Math.PI / 2, 0, 0]} receiveShadow>
        <circleGeometry args={[6.55, 8]} />
        <meshStandardMaterial color={PLATE} metalness={0.62} roughness={0.52} />
      </mesh>

      {/* 侧面发光环带 */}
      <mesh position={[0, -0.4, 0]}>
        <cylinderGeometry args={[6.68, 6.74, 0.12, 8, 1, true]} />
        <meshStandardMaterial
          ref={ringMat}
          color="#071521"
          emissive="#2ea8d8"
          emissiveIntensity={0.6}
          metalness={0.9}
          roughness={0.25}
          side={THREE.DoubleSide}
        />
      </mesh>

      {/* 顶面外缘光边 */}
      <mesh position={[0, 0.035, 0]} rotation={[-Math.PI / 2, 0, 0]}>
        <ringGeometry args={[6.16, 6.34, 64]} />
        <meshStandardMaterial
          color="#04121c"
          emissive="#3fe3ff"
          emissiveIntensity={1.5}
          toneMapped={false}
          side={THREE.DoubleSide}
        />
      </mesh>

      {/* 环形轨道 */}
      <mesh position={[0, 0.03, 0]} rotation={[-Math.PI / 2, 0, 0]}>
        <ringGeometry args={[4.22, 4.3, 128]} />
        <meshStandardMaterial
          color="#04121c"
          emissive="#2d7fa8"
          emissiveIntensity={0.9}
          toneMapped={false}
          side={THREE.DoubleSide}
          transparent
          opacity={0.85}
        />
      </mesh>

      {/* 内圈 */}
      <mesh position={[0, 0.03, 0]} rotation={[-Math.PI / 2, 0, 0]}>
        <ringGeometry args={[1.24, 1.3, 96]} />
        <meshStandardMaterial
          color="#04121c"
          emissive="#3fe3ff"
          emissiveIntensity={0.8}
          toneMapped={false}
          side={THREE.DoubleSide}
          transparent
          opacity={0.7}
        />
      </mesh>

      {/* 辐条 */}
      {spokes.map((s) => (
        <mesh key={s.id} position={[s.x, 0.028, s.z]} rotation={[-Math.PI / 2, 0, s.rot]}>
          <planeGeometry args={[3.0, 0.045]} />
          <meshStandardMaterial
            color="#04121c"
            emissive="#1d5f8a"
            emissiveIntensity={0.7}
            toneMapped={false}
            side={THREE.DoubleSide}
            transparent
            opacity={0.55}
          />
        </mesh>
      ))}

      {/* 底部倒锥体 */}
      <mesh position={[0, -3.3, 0]}>
        <coneGeometry args={[6.2, 5.6, 8]} />
        <meshStandardMaterial color="#05080f" metalness={0.7} roughness={0.65} />
      </mesh>

      {/* 锥体上的两道发光带 */}
      {[-1.6, -2.9].map((y, i) => (
        <mesh key={y} position={[0, y, 0]}>
          <cylinderGeometry args={[4.0 - i * 1.5, 4.15 - i * 1.5, 0.06, 8, 1, true]} />
          <meshStandardMaterial
            color="#05121c"
            emissive="#1d6f9a"
            emissiveIntensity={0.75}
            toneMapped={false}
            side={THREE.DoubleSide}
          />
        </mesh>
      ))}

      {/* 底部柔光 */}
      <mesh position={[0, -1.2, 0]} rotation={[-Math.PI / 2, 0, 0]}>
        <planeGeometry args={[26, 26]} />
        <meshBasicMaterial
          map={halo}
          transparent
          opacity={0.55}
          depthWrite={false}
          blending={THREE.AdditiveBlending}
        />
      </mesh>
    </group>
  );
}
