/* --------------------------------------------------------- Lux3D 生成的 GLB 道具 */

export function ModelProp({ url, height = 1.5 }: { url: string; height?: number }) {
  const { scene } = useGLTF(url);
  const grp = useRef<THREE.Group>(null!);

  const prepared = useMemo(() => {
    const root = scene.clone(true);
    root.updateWorldMatrix(true, true);
    const box = new THREE.Box3().setFromObject(root);
    const size = box.getSize(new THREE.Vector3());
    const center = box.getCenter(new THREE.Vector3());
    const s = height / Math.max(size.y, 1e-4);
    return { root, s, center, minY: box.min.y };
  }, [scene, height]);

  useFrame((st) => {
    if (grp.current) grp.current.rotation.y = st.clock.elapsedTime * 0.22;
  });

  return (
    <group ref={grp}>
      <primitive
        object={prepared.root}
        scale={prepared.s}
        position={[-prepared.center.x * prepared.s, -prepared.minY * prepared.s + 0.14, -prepared.center.z * prepared.s]}
      />
    </group>
  );
}

/* ------------------------------------------------------------------------ 注册 */

export const PROCEDURAL: Record<string, () => JSX.Element> = {
  reason: CrystalCore,
  perceive: EyeOrb,
  retrieve: RadarDish,
  act: RobotArm,
  verify: BalanceScale,
  answer: PortalGate,
};

/** 探测某个工位是否已经有 Lux3D 生成的模型 */
const availability = new Map<string, boolean>();

export async function probeAsset(id: string): Promise<boolean> {
  if (availability.has(id)) return availability.get(id)!;
  let ok = false;
  try {
    const r = await fetch(`/models/${id}.glb`, { method: "HEAD" });
    ok = r.ok && Number(r.headers.get("content-length") ?? "1") > 200;
  } catch {
    ok = false;
  }
  availability.set(id, ok);
  return ok;
}
