/* ------------------------------------------------------------------ 推理水晶 */

export function CrystalCore() {
  const grp = useRef<THREE.Group>(null!);
  const core = useRef<THREE.Mesh>(null!);
  const outerMat = useRef<THREE.MeshStandardMaterial>(null!);
  const innerMat = useRef<THREE.MeshStandardMaterial>(null!);
  const ring = useRef<THREE.Mesh>(null!);
  const ring2 = useRef<THREE.Mesh>(null!);
  const light = useRef<THREE.PointLight>(null!);

  useFrame((s) => {
    const t = s.clock.elapsedTime;
    const e = energy("reason");
    grp.current.rotation.y = t * 0.22;
    grp.current.position.y = 1.15 + Math.sin(t * 0.85) * 0.05 + e * 0.15;
    core.current.rotation.y = -t * 0.8;
    core.current.rotation.x = Math.sin(t * 0.4) * 0.22;
    outerMat.current.emissiveIntensity = 1.1 + e * 3.4 + Math.sin(t * 2.1) * 0.1;
    innerMat.current.emissiveIntensity = 2.4 + e * 5.0;
    ring.current.rotation.z = t * 0.6;
    ring.current.scale.setScalar(1 + e * 0.24);
    ring2.current.rotation.y = -t * 0.45;
    ring2.current.scale.setScalar(1 + e * 0.14);
    light.current.intensity = 3 + e * 12;
  });

  return (
    <group ref={grp} position={[0, 1.15, 0]}>
      <mesh ref={core}>
        <octahedronGeometry args={[0.8, 0]} />
        <meshStandardMaterial
          ref={outerMat}
          color="#0b3040"
          emissive="#35d8ff"
          emissiveIntensity={1.4}
          metalness={0.25}
          roughness={0.08}
          transparent
          opacity={0.93}
          flatShading
        />
      </mesh>
      <mesh>
        <icosahedronGeometry args={[0.34, 0]} />
        <meshStandardMaterial
          ref={innerMat}
          color="#ffffff"
          emissive="#c8fbff"
          emissiveIntensity={2.6}
          toneMapped={false}
        />
      </mesh>
      <mesh ref={ring} rotation={[Math.PI / 2, 0, 0]}>
        <torusGeometry args={[1.08, 0.011, 8, 96]} />
        <meshStandardMaterial color="#04222e" emissive="#3fe3ff" emissiveIntensity={2} toneMapped={false} />
      </mesh>
      <mesh ref={ring2} rotation={[Math.PI / 2.6, 0.4, 0]}>
        <torusGeometry args={[1.3, 0.007, 8, 96]} />
