}

/* -------------------------------------------------------------------- 感知之眼 */

export function EyeOrb() {
  const grp = useRef<THREE.Group>(null!);
  const iris = useRef<THREE.Group>(null!);
  const pupil = useRef<THREE.Mesh>(null!);
  const mat = useRef<THREE.MeshStandardMaterial>(null!);

  useFrame((s) => {
    const t = s.clock.elapsedTime;
    const e = energy("perceive");
    // 眨眼
    const blinkPhase = (t % 4.6) / 4.6;
    const blink = blinkPhase > 0.94 ? Math.max(0.05, 1 - (blinkPhase - 0.94) / 0.06) : 1;
    grp.current.scale.set(1, blink, 1);
    grp.current.position.y = 0.72 + Math.sin(t * 1.1) * 0.04;
    grp.current.rotation.z = Math.sin(t * 0.7) * 0.05;
    iris.current.scale.setScalar(1 + e * 0.3);
    mat.current.emissiveIntensity = 1.1 + e * 3.6;
    pupil.current.scale.setScalar(1 + e * 0.28);
  });

  return (
    <group ref={grp} position={[0, 0.72, 0]}>
      <mesh>
        <sphereGeometry args={[0.44, 40, 28]} />
