      <mesh position={[0, 0, 0.16]} scale={[1, 1, 0.75]}>
        <sphereGeometry args={[0.37, 32, 24]} />
        <meshStandardMaterial color="#0a1420" metalness={0.4} roughness={0.3} />
      </mesh>
      <group ref={iris} position={[0, 0, 0.36]}>
        <mesh>
