{"content": "import { useEffect, useMemo, useRef, useState } from "react";
import * as THREE from "three";
import { useFrame } from "@react-three/fiber";
import { Html } from "@react-three/drei";
import { STATIONS, type StationId } from "../engine/types";
import { STATION_ACCENT } from "../engine/theme";
import { energy, fx } from "../engine/fx";
import { polar } from "./util";
import { PROCEDURAL, ModelProp, probeAsset } from "./Props";

const RING_IDS: StationId[] = ["perceive", "retrieve", "act", "verify", "answer"];

export function useStationAssets() {
  const [assets, setAssets] = useState<Record<string, boolean>>({});
  useEffect(() => {
    let alive = true;
    Promise.all(RING_IDS.concat("reason").map(async (id) => [id, await probeAsset(id)] as const))
      .then((pairs) => {
        if (!alive) return;
        setAssets(Object.fromEntries(pairs));
      })
      .catch(() => void 0);
    return () => {
      alive = false;
    };
  }, []);
  return assets;
}

function Ping({ station }: { station: StationId }) {
  const mesh = useRef<THREE.Mesh>(null!);
  const mat = useRef<THREE.MeshBasicMaterial>(null!);
  useFrame(() => {
    const e = energy(station);
    if (mesh.current) {
      const s = 1 + (1 - e) * 2.2;
      mesh.current.scale.setScalar(s);
    }
    if (mat.current) mat.current.opacity = Math.max(0, e * 0.75);
  });
  const accent = STATION_ACCENT[station];
  return (
    <mesh ref={mesh} rotation={[-Math.PI / 2, 0, 0]} position={[0, 0.19, 0]}>
      <ringGeometry args={[0.62, 0.7, 48]} />
      <meshBasicMaterial
        ref={mat}
        color={accent}
        transparent
        opacity={0}
        toneMapped={false}
        depthWrite={false}
        side={THREE.DoubleSide}
        blending={THREE.AdditiveBlending}
      />
    </mesh>
  );
}

function Label({ station }: { station: StationId }) {
  const meta = STATIONS[station];
  const accent = STATION_ACCENT[station];
  const ref = useRef<HTMLDivElement>(null);
  useFrame(() => {
    const e = energy(station);
    if (ref.current) {
      ref.current.style.setProperty("--pulse", String(e));
    }
  });
  return (
    <Html center position={[0, 2.32, 0]} distanceFactor={13} zIndexRange={[30, 0]}>
      <div className="st-label" ref={ref} style={{ ["--acc" as string]: accent }}>
        <span className="st-dot" />
        <span className="st-cn">{meta.name}</span>
        <span className="st-en">{meta.en}</span>
      </div>
    </Html>
  );
}

function Station({ id, modelUrl, showLabel = true }: { id: StationId; modelUrl: string | null; showLabel?: boolean }) {
  const meta = STATIONS[id];
  const [x, z] = polar(meta.angle, meta.radius);
  const rotY = Math.PI / 2 - (meta.angle * Math.PI) / 180;
  const accent = STATION_ACCENT[id];

  const column = useRef<THREE.Mesh>(null!);
  const colMat = useRef<THREE.MeshBasicMaterial>(null!);
  const padRing = useRef<THREE.MeshStandardMaterial>(null!);

  useFrame(() => {
    const e = energy(id);
    if (colMat.current) colMat.current.opacity = e * 0.16;
