import * as THREE from "three";
import { useFrame } from "@react-three/fiber";
import { Html } from "@react-three/drei";
import { STATIONS, type StationId } from "../engine/types";
import { STATION_ACCENT } from "../engine/theme";
import { energy, fx } from "../engine/fx";
import { polar } from "./util";
import { PROCEDURAL, ModelProp, probeAsset } from "./Props";

const RING_IDS: StationId[] = ["perceive", "retrieve", "act", "verify", "answer"];

export function useStationAssets() {
  const [assets, setAssets] = useState<Record<string, boolean>>({});
  useEffect(() => {
    let alive = true;
    Promise.all(RING_IDS.concat("reason").map(async (id) => [id, await probeAsset(id)] as const))
      .then((pairs) => {
        if (!alive) return;
        setAssets(Object.fromEntries(pairs));
      })
      .catch(() => void 0);
    return () => {
      alive = false;
    };
  }, []);
  return assets;
}

function Ping({ station }: { station: StationId }) {
  const mesh = useRef<THREE.Mesh>(null!);
  const mat = useRef<THREE.MeshBasicMaterial>(null!);
  useFrame(() => {
    const e = energy(station);
    if (mesh.current) {
      const s = 1 + (1 - e) * 2.2;
      mesh.current.scale.setScalar(s);
    }
    if (mat.current) mat.current.opacity = Math.max(0, e * 0.75);
  });
