```tsx
function Choreographer() {
  const seq = useMind(s => s.seq);
  const idx = useMind(s => s.activeIndex);
  const trace = useMind(s => s.trace);
  const prev = useRef<StationId | null>(null);
  const prevPos = useRef(new THREE.Vector3(...stationPosition("reason")));

  useEffect(() => {
    const ev = trace[idx];
    if (!ev) return;
    const cur = new THREE.Vector3(...stationPosition(ev.station));
    pulse(ev.station);
    const color = KIND_COLOR[ev.kind];
    fx.travel(prevPos.current, cur, color, 0.9);
    pulse arrival -> burst handled in update onArrive
    prev.current = ev.station; prevPos.current = cur;
    if (ev.kind === "answer") { ... }
  }, [seq]);
}
```

