export function CameraRig() {
  const { camera } = useThree();
  const focus = useMind(s => s.focus);
  const viewMode = useMind(s => s.viewMode);
  const target = useMemo(() => new THREE.Vector3(0, 1.5, 0), []);
  const desiredPos = useMemo(() => new THREE.Vector3(11, 8.6, 11), []);
  const desiredTarget = useMemo(() => new THREE.Vector3(0, 1.5, 0), []);
  const intro = useRef(0);

  useEffect(() => {
    if (viewMode !== "cinematic") return;
    const p = new THREE.Vector3(...stationPosition(focus));
    if (focus === "reason") {
      desiredTarget.set(0, 1.5, 0);
      desiredPos.set(4.2, 5.2, 8.6);
    } else {
      const dir = p.clone().setY(0).normalize();
      desiredTarget.copy(p).setY(1.1);
      desiredPos.copy(p).addScaledVector(dir, 5.0).add(new THREE.Vector3(0, 3.4, 0));
    }
  }, [focus, viewMode]);
```

