{"content": "import { useEffect, useMemo, useRef } from "react";
import * as THREE from "three";
import { useFrame, useThree } from "@react-three/fiber";
import { fx, MAX_MOTES, MAX_SPARKS, pulse } from "../engine/fx";
import { stationPosition, type StationId } from "../engine/types";
import { KIND_COLOR, STATION_ACCENT } from "../engine/theme";
import { useMind, mind } from "../engine/store";

/* ----------------------------------------------------------- 每帧推进播放头 */

export function Ticker() {
  useFrame((_, dt) => {
    mind().tick(Math.min(dt, 0.05) * 1000);
  });
  return null;
}

/* --------------------------------------------------------------- 粒子系统 */

const CAP = MAX_SPARKS + MAX_MOTES;

export function Particles() {
  const geo = useMemo(() => {
    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.BufferAttribute(new Float32Array(CAP * 3), 3));
    g.setAttribute("aColor", new THREE.BufferAttribute(new Float32Array(CAP * 3), 3));
    g.setAttribute("aSize", new THREE.BufferAttribute(new Float32Array(CAP), 1));
    g.setAttribute("aAlpha", new THREE.BufferAttribute(new Float32Array(CAP), 1));
    g.setDrawRange(0, 0);
    return g;
  }, []);

  const mat = useMemo(
    () =>
      new THREE.ShaderMaterial({
        uniforms: { uScale: { value: 320 } },
        vertexShader: /* glsl */ `
          attribute vec3 aColor;
          attribute float aSize;
          attribute float aAlpha;
          uniform float uScale;
          varying vec3 vC;
          varying float vA;
          void main() {
            vC = aColor;
            vA = aAlpha;
            vec4 mv = modelViewMatrix * vec4(position, 1.0);
            gl_PointSize = aSize * uScale / max(0.001, -mv.z);
            gl_Position = projectionMatrix * mv;
          }
        `,
        fragmentShader: /* glsl */ `
          varying vec3 vC;
          varying float vA;
          void main() {
            vec2 uv = gl_PointCoord - 0.5;
            float d = length(uv);
            if (d > 0.5) discard;
            float a = smoothstep(0.5, 0.0, d);
            a = pow(a, 1.7);
            gl_FragColor = vec4(vC * (0.5 + a * 1.9), a * vA);
          }
        `,
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
      }),
    [],
  );

  const tmpV = useMemo(() => new THREE.Vector3(), []);

  useFrame((_, dt) => {
    const d = Math.min(dt, 0.05);
    fx.update(d, (m) => {
      fx.burst(m.to, m.color, 24, 3.4);
    });

    const pos = geo.attributes.position as THREE.BufferAttribute;
    const col = geo.attributes.aColor as THREE.BufferAttribute;
    const siz = geo.attributes.aSize as THREE.BufferAttribute;
    const alp = geo.attributes.aAlpha as THREE.BufferAttribute;

    let n = 0;

    for (const m of fx.motes) {
      if (n >= CAP) break;
      fx.positionAt(m, tmpV);
      pos.setXYZ(n, tmpV.x, tmpV.y, tmpV.z);
      col.setXYZ(n, m.color.r, m.color.g, m.color.b);
      siz.setX(n, 0.55);
      alp.setX(n, 1);
      n++;
    }

    for (const s of fx.sparks) {
      if (n >= CAP) break;
      const lifeRatio = Math.max(0, Math.min(1, s.life / 0.9));
      pos.setXYZ(n, s.p.x, s.p.y, s.p.z);
      col.setXYZ(n, s.color.r, s.color.g, s.color.b);
      siz.setX(n, s.size * 0.13);
      alp.setX(n, lifeRatio);
      n++;
    }

    pos.needsUpdate = true;
    col.needsUpdate = true;
    siz.needsUpdate = true;
    alp.needsUpdate = true;
    geo.setDrawRange(0, n);
  });

  return <points geometry={geo} material={mat} frustumCulled={false} />;
}

/* ----------------------------------------------------------------- 场景浮尘 */

export function Dust() {
  const grp = useRef<THREE.Group>(null!);
  const { count, positions } = useMemo(() => {
    const count = 1100;
    const positions = new Float32Array(count * 3);
    for (let i = 0; i < count; i++) {
      const r = 3.5 + Math.pow(Math.random(), 0.7) * 20;
      const a = Math.random() * Math.PI * 2;
      positions[i * 3] = Math.cos(a) * r;
      positions[i * 3 + 1] = -5 + Math.random() * 20;
      positions[i * 3 + 2] = Math.sin(a) * r;
    }
    return { count, positions };
  }, []);

  useFrame((s, dt) => {
    if (!grp.current) return;
    grp.current.rotation.y += dt * 0.012;
    grp.current.position.y = Math.sin(s.clock.elapsedTime * 0.15) * 0.35;
  });

  const tex = useMemo(() => {
    const c = document.createElement("canvas");
    c.width = c.height = 32;
    const ctx = c.getContext("2d")!;
    const g = ctx.createRadialGradient(16, 16, 0, 16, 16, 16);
    g.addColorStop(0, "rgba(255,255,255,1)");
    g.addColorStop(1, "rgba(255,255,255,0)");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, 32, 32);
    return new THREE.CanvasTexture(c);
  }, []);

  return (
    <group ref={grp}>
      <points>
        <bufferGeometry>
          <bufferAttribute attach="attributes-position" args={[positions, 3]} count={count} />
        </bufferGeometry>
        <pointsMaterial
          map={tex}
          size={0.12}
          sizeAttenuation
          transparent
          opacity={0.5}
          depthWrite={false}
          blending={THREE.AdditiveBlending}
          color="#9fd4ff"
        />
      </points>
    </group>
  );
}

/* --------------------------------------------------------------- 编排（导演） */

const FINALE_STATIONS: StationId[] = ["perceive", "retrieve", "act", "verify", "answer"];

export function Choreographer() {
  const seq = useMind((s) => s.seq);
  const idx = useMind((s) => s.activeIndex);
  const trace = useMind((s) => s.trace);
  const prevPos = useRef(new THREE.Vector3(0, 2, 0));
  const timers = useRef<number[]>([]);

  useEffect(() => {
    for (const t of timers.current) window.clearTimeout(t);
    timers.current = [];

    const ev = trace[idx];
    if (!ev) return;

    const cur = new THREE.Vector3(...stationPosition(ev.station));
    pulse(ev.station);

    const color = KIND_COLOR[ev.kind];
    fx.travel(prevPos.current, cur, color, 0.95);
    prevPos.current = cur;

    if (ev.kind === "error") {
      timers.current.push(
        window.setTimeout(() => {
          fx.burst(cur, "#ff5d7a", 46, 4.2);
        }, 950) as unknown as number,
      );
    }

    if (ev.kind === "answer") {
      timers.current.push(
        window.setTimeout(() => {
          fx.shock(new THREE.Vector3(0, 1.1, 0), "#ffd166", 110, 7.2);
          for (const id of FINALE_STATIONS) {
            fx.burst(new THREE.Vector3(...stationPosition(id)), STATION_ACCENT[id], 22, 3.2);
          }
        }, 700) as unknown as number,
      );
    }
  }, [seq, idx, trace]);

  useEffect(() => {
    return () => {
      for (const t of timers.current) window.clearTimeout(t);
    };
  }, []);

  return null;
}

/* ---------------------------------------------------------------- 背景星空 */

export function Backdrop() {
  const { camera } = useThree();
  useEffect(() => {
    camera.lookAt(0, 1.4, 0);
  }, [camera]);
  return null;
}
