{"content": "import { useEffect, useRef } from "react";
import * as THREE from "three";
import { useFrame, useThree } from "@react-three/fiber";
import { OrbitControls } from "@react-three/drei";
import { stationPosition } from "../engine/types";
import { useMind } from "../engine/store";

export function CameraRig() {
  const { camera } = useThree();
  const focus = useMind((s) => s.focus);
  const seq = useMind((s) => s.seq);
  const viewMode = useMind((s) => s.viewMode);

  const desiredPos = useRef(new THREE.Vector3(11.5, 9, 11.5));
  const desiredTarget = useRef(new THREE.Vector3(0, 1.5, 0));
  const target = useRef(new THREE.Vector3(0, 1.5, 0));

  useEffect(() => {
    if (viewMode !== "cinematic") return;
    if (focus === "reason") {
      desiredTarget.current.set(0, 1.5, 0);
      desiredPos.current.set(4.8, 5.0, 8.6);
      return;
    }
    const p = new THREE.Vector3(...stationPosition(focus));
    const dir = p.clone().setY(0).normalize();
    desiredTarget.current.copy(p).setY(1.2);
    desiredPos.current.copy(p).addScaledVector(dir, 4.7);
    desiredPos.current.y += 3.0;
  }, [focus, seq, viewMode]);

  useFrame((state, dt) => {
    if (viewMode !== "cinematic") return;
    const d = Math.min(dt, 0.05);
    const t = state.clock.elapsedTime;
    const nx = Math.sin(t * 0.31) * 0.1;
    const ny = Math.cos(t * 0.23) * 0.07;

    camera.position.x = THREE.MathUtils.damp(camera.position.x, desiredPos.current.x + nx, 1.7, d);
    camera.position.y = THREE.MathUtils.damp(camera.position.y, desiredPos.current.y + ny, 1.7, d);
    camera.position.z = THREE.MathUtils.damp(camera.position.z, desiredPos.current.z + nx, 1.7, d);

    target.current.x = THREE.MathUtils.damp(target.current.x, desiredTarget.current.x, 2.6, d);
    target.current.y = THREE.MathUtils.damp(target.current.y, desiredTarget.current.y, 2.6, d);
    target.current.z = THREE.MathUtils.damp(target.current.z, desiredTarget.current.z, 2.6, d);

    camera.lookAt(target.current);
  });

  if (viewMode === "orbit") {
    return (
      <OrbitControls
        makeDefault
        enablePan={false}
        minDistance={7}
        maxDistance={26}
        minPolarAngle={0.25}
        maxPolarAngle={Math.PI / 2.15}
        target={[0, 1.2, 0]}
        enableDamping
        dampingFactor={0.08}
      />
    );
  }
  return null;
}
