{"content": "import { Suspense } from "react";
import { Canvas } from "@react-three/fiber";
import * as THREE from "three";
import { ContactShadows, Environment, Lightformer } from "@react-three/drei";
import { EffectComposer, Bloom, Vignette } from "@react-three/postprocessing";
import { Platform } from "./Platform";
import { Stations } from "./Stations";
import { CameraRig } from "./CameraRig";
import { Choreographer, Dust, Particles, Ticker } from "./Fx";

function Effects() {
  return (
    <EffectComposer multisampling={0}>
      <Bloom intensity={1.05} luminanceThreshold={0.2} luminanceSmoothing={0.4} mipmapBlur radius={0.72} />
      <Vignette offset={0.26} darkness={0.72} />
    </EffectComposer>
  );
}

export function Diorama() {
  return (
    <Canvas
      shadows
      dpr={[1, 1.75]}
      gl={{ antialias: true, powerPreference: "high-performance", stencil: false }}
      camera={{ position: [17, 13, 17], fov: 38, near: 0.5, far: 140 }}
      onCreated={({ gl }) => {
        gl.toneMapping = THREE.ACESFilmicToneMapping;
        gl.toneMappingExposure = 1.05;
      }}
    >
      <color attach="background" args={["#05070e"]} />
      <fog attach="fog" args={["#05070e", 26, 62]} />

      <ambientLight intensity={0.5} />
      <directionalLight
        position={[9, 15, 7]}
        intensity={2.1}
        color="#dbe9ff"
        castShadow
        shadow-mapSize={[1024, 1024]}
        shadow-camera-left={-12}
        shadow-camera-right={12}
        shadow-camera-top={12}
        shadow-camera-bottom={-12}
        shadow-camera-far={40}
        shadow-bias={-0.0008}
      />
      <directionalLight position={[-11, 7, -9]} intensity={1.15} color="#7a5cff" />
      <pointLight position={[0, 4.2, 0]} intensity={2.4} color="#35d8ff" distance={18} decay={2} />

      <Suspense fallback={null}>
        <Environment resolution={256} frames={1}>
          <Lightformer
            form="rect"
            intensity={4}
            color="#5b8cff"
            position={[0, 9, 0]}
            rotation={[Math.PI / 2, 0, 0]}
            scale={[16, 16, 1]}
          />
          <Lightformer
            form="rect"
            intensity={2.2}
            color="#35e3ff"
            position={[-9, 3, 5]}
            rotation={[0, Math.PI / 2, 0]}
            scale={[10, 6, 1]}
          />
          <Lightformer
            form="rect"
            intensity={1.9}
            color="#8a5cff"
            position={[9, 4, -6]}
            rotation={[0, -Math.PI / 2, 0]}
            scale={[10, 6, 1]}
          />
        </Environment>
      </Suspense>

      <Platform />
      <Stations />

      <ContactShadows
        position={[0, 0.205, 0]}
        opacity={0.45}
        scale={15}
        blur={2.6}
        far={4}
        resolution={512}
        color="#000000"
      />

      <Dust />
      <Particles />

      <CameraRig />
      <Choreographer />
      <Ticker />
      <Effects />
    </Canvas>
  );
}
