      </div>
    </header>
  );
}

/* ------------------------------------------------------------------ 轨迹列表 */

export function TraceList() {
  const trace = useMind((s) => s.trace);
  const activeIndex = useMind((s) => s.activeIndex);
  const seek = useMind((s) => s.seek);
  const listRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const el = listRef.current?.querySelector<HTMLElement>(".row.on");
    if (el && listRef.current) {
      const c = listRef.current;
      const top = el.offsetTop - c.clientHeight / 2 + el.clientHeight / 2;
      c.scrollTo({ top, behavior: "smooth" });
    }
  }, [activeIndex]);

  return (
    <aside className="panel trace-panel">
      <div className="panel-head">
        <span className="panel-title">执行轨迹</span>
        <span className="panel-count">
          {Math.max(0, activeIndex + 1)} / {trace.length}
        </span>
      </div>
      <div className="trace-list" ref={listRef}>
        {trace.map((e, i) => {
          const color = KIND_COLOR[e.kind];
          const state = i === activeIndex ? "on" : i < activeIndex ? "done" : "";
          return (
            <div key={e.id} className={`row ${state}`} onClick={() => seek(e.t)}>
              <span className="row-time">{fmt(e.t)}s</span>
              <span className="row-dot" style={{ background: color, boxShadow: `0 0 8px ${color}` }} />
              <div className="row-body">
                <div className="row-head">
                  <span className="row-kind" style={{ color }}>
                    {KIND_LABEL[e.kind]}
                  </span>
                  <span className="row-title">{e.title}</span>
                </div>
                {e.tool && <code className="row-tool">{e.tool}</code>}
              </div>
            </div>
          );
        })}
      </div>
    </aside>
  );
}

/* ------------------------------------------------------------------ 当前事件 */

export function DetailCard() {
  const activeIndex = useMind((s) => s.activeIndex);
  const trace = useMind((s) => s.trace);
  const ev = trace[activeIndex];

  const stats = useMemo(() => {
    let tokens = 0;
    let ms = 0;
    for (let i = 0; i <= activeIndex && i < trace.length; i++) {
      tokens += trace[i].tokens ?? 0;
      ms += trace[i].ms ?? 0;
    }
    return { tokens, ms };
  }, [activeIndex, trace]);

  if (!ev) {
    return (
      <aside className="panel detail-panel">
        <div className="panel-head">
          <span className="panel-title">当前动作</span>
        </div>
        <div className="detail-empty">
          <div className="detail-empty-ring" />
          <p>等待第一条推理…</p>
        </div>
      </aside>
    );
  }

  const color = KIND_COLOR[ev.kind];
  const station = STATIONS[ev.station];

  return (
    <aside className="panel detail-panel">
      <div className="panel-head">
        <span className="panel-title">当前动作</span>
        <span className="panel-live" style={{ color }}>
          ● LIVE
        </span>
      </div>

      <div className="detail-card" style={{ ["--acc" as string]: color }}>
        <div className="detail-tags">
          <span className="tag" style={{ color, borderColor: `${color}55` }}>
            {KIND_LABEL[ev.kind]}
          </span>
          <span
            className="tag ghost"
            style={{ color: STATION_ACCENT[ev.station], borderColor: `${STATION_ACCENT[ev.station]}44` }}
          >
            {station.name} · {station.en}
          </span>
        </div>

        <h2 className="detail-title">{ev.title}</h2>
        {ev.detail && <p className="detail-desc">{ev.detail}</p>}
        {ev.tool && <code className="detail-tool">{ev.tool}</code>}
      </div>

      <div className="stat-row">
        <div className="stat">
          <span className="stat-k">累计 token</span>
          <span className="stat-v">{stats.tokens.toLocaleString()}</span>
        </div>
        <div className="stat">
          <span className="stat-k">工具耗时</span>
          <span className="stat-v">{(stats.ms / 1000).toFixed(1)}s</span>
        </div>
        <div className="stat">
          <span className="stat-k">步骤</span>
          <span className="stat-v">{activeIndex + 1}</span>
        </div>
      </div>

      <div className="station-mini">
        {(["perceive", "retrieve", "act", "verify", "answer", "reason"] as const).map((id) => {
          const on = ev.station === id;
