          <button key={s} className={`speed ${speed === s ? "on" : ""}`} onClick={() => setSpeed(s)}>
            {s}×
          </button>
        ))}
      </div>

      <div className="spacer" />

      <div className="clock">
        <span className="clock-cur">{fmt(playhead)}s</span>
        <span className="clock-sep">/</span>
        <span className="clock-total">{fmt(totalMs)}s</span>
      </div>

      <div className="view-toggle">
        <button
          className={`vt ${viewMode === "cinematic" ? "on" : ""}`}
          onClick={() => setViewMode("cinematic")}
          title="导演运镜：镜头跟随当前工位"
        >
          导演运镜
        </button>
        <button
          className={`vt ${viewMode === "orbit" ? "on" : ""}`}
          onClick={() => setViewMode("orbit")}
          title="自由视角：鼠标拖拽旋转"
        >
          自由视角
        </button>
      </div>

      <span className="step-ind">{activeIndex >= 0 ? `#${activeIndex + 1}` : "#0"}</span>
    </div>
  );
}

/* ----------------------------------------------------------------------- HUD */

export function Hud() {
  return (
    <div className="hud">
      <TopBar />
      <TraceList />
      <DetailCard />
      <div className="bottom">
        <Timeline />
        <Controls />
      </div>
    </div>
  );
}
