{"content": "import { useEffect } from "react";
import { Diorama } from "./scene/Diorama";
import { Hud } from "./ui/Hud";
import { useMind } from "./engine/store";

export default function App() {
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const s = useMind.getState();
      if (e.code === "Space") {
        e.preventDefault();
        s.toggle();
        return;
      }
      if (e.code === "ArrowRight") {
        const next = s.trace.find((ev) => ev.t > s.playhead + 60);
        s.seek(next ? next.t : s.totalMs);
        return;
      }
      if (e.code === "ArrowLeft") {
        const prev = [...s.trace].reverse().find((ev) => ev.t < s.playhead - 60);
        s.seek(prev ? prev.t : 0);
        return;
      }
      if (e.key === "r" || e.key === "R") {
        s.reset();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  return (
    <div className="app">
      <div className="stage">
        <Diorama />
      </div>
      <Hud />
      <div className="vignette-overlay" />
    </div>
  );
}
