{"content": ":root {
  --bg: #05070e;
  --ink: #e8f0ff;
  --muted: #7d8ea8;
  --dim: #4c5b72;
  --line: rgba(120, 170, 230, 0.14);
  --panel: rgba(9, 14, 24, 0.62);
  --cyan: #3fe3ff;
  --gold: #ffd166;
  --radius: 14px;
  --mono: ui-monospace, "SF Mono", "JetBrains Mono", "Cascadia Code", Consolas, monospace;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  overflow: hidden;
  font-family: "Inter", "Segoe UI", "PingFang SC", "Microsoft YaHei", system-ui, -apple-system, sans-serif;
  -webkit-font-smoothing: antialiased;
}

.app {
  position: fixed;
  inset: 0;
}

.stage {
  position: absolute;
  inset: 0;
}

.stage canvas {
  display: block;
  outline: none;
}

.vignette-overlay {
  position: fixed;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(125% 95% at 50% 44%, transparent 42%, rgba(0, 0, 0, 0.42) 100%);
  z-index: 1;
}

/* ------------------------------------------------------------------ HUD 布局 */

.hud {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 2;
}

.panel {
  position: absolute;
  pointer-events: auto;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  backdrop-filter: blur(16px) saturate(1.2);
  -webkit-backdrop-filter: blur(16px) saturate(1.2);
  box-shadow: 0 18px 48px -24px rgba(0, 0, 0, 0.9), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  animation: rise 0.7s cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

/* -------------------------------------------------------------------- 顶部栏 */

.top {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  display: flex;
  align-items: center;
  gap: 22px;
  padding: 18px 24px;
  pointer-events: none;
}

.brand {
  display: flex;
  align-items: center;
  gap: 13px;
}

.brand-mark {
  position: relative;
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
}

.brand-mark i {
  position: absolute;
  display: block;
  border: 1.5px solid var(--cyan);
  border-radius: 4px;
  opacity: 0.85;
  animation: spin 9s linear infinite;
}

.brand-mark i:nth-child(1) {
  width: 26px;
  height: 26px;
  box-shadow: 0 0 16px -2px var(--cyan);
}

.brand-mark i:nth-child(2) {
  width: 18px;
  height: 18px;
  border-color: #8a6bff;
  animation-direction: reverse;
  animation-duration: 6s;
}

.brand-mark i:nth-child(3) {
  width: 7px;
  height: 7px;
  background: var(--cyan);
  border: none;
  border-radius: 50%;
  box-shadow: 0 0 14px 2px var(--cyan);
  animation: none;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.brand-text h1 {
  margin: 0;
  font-size: 19px;
  font-weight: 700;
  letter-spacing: 0.02em;
  display: flex;
  align-items: baseline;
  gap: 9px;
}

.brand-text h1 span {
  font-family: var(--mono);
  font-size: 10.5px;
  letter-spacing: 0.28em;
  color: var(--cyan);
  opacity: 0.8;
  font-weight: 500;
}

.brand-text p {
  margin: 3px 0 0;
  font-size: 11.5px;
  color: var(--muted);
  letter-spacing: 0.02em;
}

.task-chip {
  display: none;
  flex-direction: column;
  gap: 2px;
  padding: 8px 16px;
  border-radius: 10px;
  border: 1px solid var(--line);
  background: rgba(8, 13, 22, 0.5);
}

@media (min-width: 1180px) {
  .task-chip {
    display: flex;
  }
}

.task-label {
  font-size: 9.5px;
  letter-spacing: 0.16em;
  color: var(--dim);
  font-family: var(--mono);
}

.task-name {
  font-size: 12.5px;
  color: #c6d5ea;
}

.badges {
  margin-left: auto;
  display: flex;
  gap: 8px;
  pointer-events: auto;
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  padding: 6px 11px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: rgba(8, 13, 22, 0.55);
  color: #b9c9e0;
  letter-spacing: 0.02em;
}

.badge.lux {
  border-color: rgba(63, 227, 255, 0.3);
  color: #bdefff;
  box-shadow: 0 0 22px -10px var(--cyan);
}

.lux-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 8px var(--cyan);
  animation: breathe 2.4s ease-in-out infinite;
}

@keyframes breathe {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.35;
  }
}

.badge.mode {
  color: #8ff0c0;
  border-color: rgba(80, 220, 160, 0.26);
}

/* ------------------------------------------------------------------ 轨迹面板 */

.trace-panel {
  left: 24px;
  top: 98px;
  width: 336px;
  bottom: 152px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 13px 16px 11px;
  border-bottom: 1px solid var(--line);
  flex: 0 0 auto;
}

.panel-title {
  font-size: 11.5px;
  letter-spacing: 0.18em;
  color: #9db1cc;
  font-weight: 600;
}

.panel-count {
  font-family: var(--mono);
  font-size: 11px;
  color: var(--dim);
}

.panel-live {
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.12em;
  animation: breathe 1.6s ease-in-out infinite;
}

.trace-list {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 8px 8px 14px;
  scrollbar-width: thin;
  scrollbar-color: rgba(120, 170, 230, 0.25) transparent;
}

.trace-list::-webkit-scrollbar {
  width: 6px;
}

.trace-list::-webkit-scrollbar-thumb {
  background: rgba(120, 170, 230, 0.22);
  border-radius: 99px;
}

.row {
  position: relative;
  display: flex;
  gap: 10px;
  padding: 9px 10px 9px 12px;
  border-radius: 10px;
  cursor: pointer;
  opacity: 0.42;
  transition: opacity 0.3s, background 0.3s, transform 0.3s;
}

.row::before {
  content: "";
  position: absolute;
  left: 3px;
  top: 12px;
  bottom: 12px;
  width: 2px;
  border-radius: 2px;
  background: transparent;
  transition: background 0.3s;
}

.row:hover {
  opacity: 0.85;
  background: rgba(120, 170, 230, 0.06);
}

.row.done {
  opacity: 0.72;
}

.row.on {
  opacity: 1;
  background: linear-gradient(90deg, rgba(63, 227, 255, 0.12), rgba(63, 227, 255, 0.02));
  transform: translateX(2px);
}

.row.on::before {
  background: var(--cyan);
  box-shadow: 0 0 12px var(--cyan);
}

.row-time {
  font-family: var(--mono);
  font-size: 10.5px;
  color: var(--dim);
  padding-top: 2px;
  min-width: 32px;
}

.row-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  margin-top: 6px;
  flex: 0 0 auto;
}

.row-body {
  min-width: 0;
  flex: 1;
}

.row-head {
  display: flex;
  gap: 7px;
  align-items: baseline;
  min-width: 0;
}

.row-kind {
  font-size: 9.5px;
  letter-spacing: 0.1em;
  flex: 0 0 auto;
  opacity: 0.9;
  font-weight: 600;
}

.row-title {
  font-size: 12.5px;
  color: #d5e2f5;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.row-tool {
  display: inline-block;
  margin-top: 4px;
  font-size: 10px;
  font-family: var(--mono);
  color: #7fb3cc;
  background: rgba(63, 227, 255, 0.07);
  border: 1px solid rgba(63, 227, 255, 0.12);
  padding: 1px 6px;
  border-radius: 5px;
}

/* ------------------------------------------------------------------ 详情面板 */

.detail-panel {
  right: 24px;
  top: 98px;
  width: 330px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.detail-empty {
  padding: 48px 20px;
  text-align: center;
  color: var(--dim);
  font-size: 12.5px;
}

.detail-empty-ring {
  width: 54px;
  height: 54px;
  margin: 0 auto 18px;
  border-radius: 50%;
  border: 1px solid rgba(63, 227, 255, 0.3);
  box-shadow: 0 0 30px -8px var(--cyan), inset 0 0 24px -10px var(--cyan);
  animation: breathe 2.6s ease-in-out infinite;
}

.detail-card {
  padding: 16px 18px 18px;
  border-left: 2px solid var(--acc, var(--cyan));
  margin: 14px 14px 0;
  border-radius: 4px 10px 10px 4px;
  background: linear-gradient(100deg, rgba(255, 255, 255, 0.045), transparent 70%);
  animation: rise 0.5s cubic-bezier(0.16, 1, 0.3, 1) both;
}

.detail-tags {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  margin-bottom: 11px;
}

.tag {
  font-size: 10px;
  letter-spacing: 0.08em;
  padding: 3px 8px;
  border-radius: 5px;
  border: 1px solid;
