}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  overflow: hidden;
  font-family: "Inter", "Segoe UI", "PingFang SC", "Microsoft YaHei", system-ui, -apple-system, sans-serif;
  -webkit-font-smoothing: antialiased;
}

.app {
  position: fixed;
  inset: 0;
}

.stage {
  position: absolute;
  inset: 0;
}

.stage canvas {
  display: block;
  outline: none;
}

.vignette-overlay {
  position: fixed;
