{"content": ":root {
  --bg: #05070e;
  --ink: #e8f0ff;
  --muted: #7d8ea8;
  --dim: #4c5b72;
  --line: rgba(120, 170, 230, 0.14);
  --panel: rgba(9, 14, 24, 0.62);
  --cyan: #3fe3ff;
  --gold: #ffd166;
  --radius: 14px;
  --mono: ui-monospace, "SF Mono", "JetBrains Mono", "Cascadia Code", Consolas, monospace;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  overflow: hidden;
  font-family: "Inter", "Segoe UI", "PingFang SC", "Microsoft YaHei", system-ui, -apple-system, sans-serif;
  -webkit-font-smoothing: antialiased;
}

.app {
  position: fixed;
  inset: 0;
}

.stage {
  position: absolute;
  inset: 0;
}

.stage canvas {
  display: block;
  outline: none;
}

.vignette-overlay {
  position: fixed;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(125% 95% at 50% 44%, transparent 42%, rgba(0, 0, 0, 0.42) 100%);
  z-index: 1;
}

/* ------------------------------------------------------------------ HUD 布局 */

.hud {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 2;
}

.panel {
  position: absolute;
  pointer-events: auto;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  backdrop-filter: blur(16px) saturate(1.2);
  -webkit-backdrop-filter: blur(16px) saturate(1.2);
  box-shadow: 0 18px 48px -24px rgba(0, 0, 0, 0.9), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  animation: rise 0.7s cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

/* -------------------------------------------------------------------- 顶部栏 */

.top {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  display: flex;
  align-items: center;
  gap: 22px;
  padding: 18px 24px;
  pointer-events: none;
}

.brand {
  display: flex;
  align-items: center;
  gap: 13px;
}

.brand-mark {
  position: relative;
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
}

.brand-mark i {
  position: absolute;
  display: block;
  border: 1.5px solid var(--cyan);
  border-radius: 4px;
  opacity: 0.85;
  animation: spin 9s linear infinite;
}

.brand-mark i:nth-child(1) {
  width: 26px;
  height: 26px;
  box-shadow: 0 0 16px -2px var(--cyan);
}

.brand-mark i:nth-child(2) {
  width: 18px;
  height: 18px;
  border-color: #8a6bff;
  animation-direction: reverse;
  animation-duration: 6s;
}

.brand-mark i:nth-child(3) {
  width: 7px;
  height: 7px;
  background: var(--cyan);
  border: none;
  border-radius: 50%;
  box-shadow: 0 0 14px 2px var(--cyan);
  animation: none;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.brand-text h1 {
  margin: 0;
  font-size: 19px;
  font-weight: 700;
  letter-spacing: 0.02em;
  display: flex;
  align-items: baseline;
  gap: 9px;
}

.brand-text h1 span {
  font-family: var(--mono);
  font-size: 10.5px;
  letter-spacing: 0.28em;
  color: var(--cyan);
  opacity: 0.8;
  font-weight: 500;
}

.brand-text p {
