import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");
const OUT_DIR = path.join(ROOT, "public", "models");

const REGION = process.env.LUX3D_REGION === "global" ? "global" : "cn";
const BASE = REGION === "global" ? "https://api.aholo.ai/global" : "https://api.aholo3d.cn";

const API_KEY = ***REDACTED***.env.AHOLO_API_KEY || process.env.LUX3D_API_KEY || "";

/* ------------------------------------------------------------------ 道具清单 */

export const ASSETS = [
  {
    id: "reason",
    prompt:
      "A floating crystal geode artifact, glowing cyan veins carved into translucent stone, " +
      "small ornate pedestal base, sci-fi museum collectible, centered, single object",
    style: "fantasy",
    height: 1.6,
  },
  {
    id: "perceive",
    prompt:
      "A cute robotic eye orb on a short brass stand, one large glass lens with glowing iris, " +
      "sci-fi laboratory instrument, white and cyan materials, single object",
    style: "cyberpunk",
    height: 1.45,
  },
  {
    id: "retrieve",
    prompt:
      "A futuristic radar dish antenna on a tripod base, curved metallic saucer with a feed antenna, " +
      "sci-fi scanning device, white and slate grey, single object",
    style: "cyberpunk",
    height: 1.45,
  },
  {
    id: "act",
    prompt:
      "An industrial robotic arm with a two finger gripper on a round base, " +
      "white ceramic body with orange accents, clean laboratory robot, single object",
    style: "cyberpunk",
    height: 1.45,
  },
  {
    id: "verify",
    prompt:
      "An ornate brass balance scale with two hanging pans and a central pillar, " +
      "steampunk precision measuring instrument, single object",
    style: "fantasy",
    height: 1.45,
  },
  {
    id: "answer",
    prompt:
      "A circular sci-fi portal gate standing upright on a base, glowing golden ring between two ornate pillars, " +
      "single object",
    style: "fantasy",
    height: 1.45,
  },
];

