/* -------------------------------------------------------------------- 主流程 */

async function processAsset(asset, opts) {
  const dest = path.join(OUT_DIR, `${asset.id}.glb`);
  console.log(`\n▶ ${asset.id}  (style=${asset.style})`);
  console.log(`  ${asset.prompt.slice(0, 90)}…`);

  const taskId = await createTextTo3D(asset, opts.faceCount);
  console.log(`  任务已创建 taskId=${taskId}`);

  const done = await waitFor(taskId, opts.timeout);
  const glbUrl = pickGlb(done.outputs);
  if (!glbUrl) throw new Error(`任务成功但没有 GLB 输出: ${JSON.stringify(done.outputs).slice(0, 300)}`);

