    id: asset.id,
    style: asset.style,
    prompt: asset.prompt,
    taskId,
    height: asset.height,
    bytes,
    file: `models/${asset.id}.glb`,
    generatedAt: new Date().toISOString(),
  };
}

async function pool(items, limit, worker) {
  const results = [];
  let cursor = 0;
  const runners = Array.from({ length: Math.min(limit, items.length) }, async () => {
    for (;;) {
      const i = cursor++;
      if (i >= items.length) return;
      try {
        results[i] = await worker(items[i], i);
      } catch (e) {
        results[i] = { error: String(e.message || e) };
        console.error(`  ✗ ${items[i].id} 失败: ${e.message || e}`);
      }
    }
  });
  await Promise.all(runners);
  return results;
}

async function main() {
  const opts = parseArgs(process.argv.slice(2));

  console.log(`Mind Forge · Lux3D 资产流水线`);
  console.log(`  区域   ${REGION}  (${BASE})`);
  console.log(`  输出   ${path.relative(ROOT, OUT_DIR)}`);

  let todo = ASSETS;
  if (opts.only) todo = todo.filter((a) => opts.only.includes(a.id));
  if (!opts.force) {
    const missing = todo.filter((a) => !fs.existsSync(path.join(OUT_DIR, `${a.id}.glb`)));
    if (missing.length !== todo.length) {
      console.log(`  跳过已存在: ${todo.filter((a) => !missing.includes(a)).map((a) => a.id).join(", ")}`);
    }
    todo = missing;
  }

  if (todo.length === 0) {
    console.log("\n全部资产已存在，加 --force 可重新生成。");
    return;
  }

  console.log(`  计划   ${todo.length} 个: ${todo.map((a) => a.id).join(", ")}`);
  console.log(`  并发   ${opts.concurrency}（免费账户上限 2）`);

  if (opts.dry) {
    console.log("\n--dry-run：不实际调用。");
    return;
  }

  if (!API_KEY) {
    console.error("\n缺少 API Key。请设置 AHOLO_API_KEY 环境变量。");
    process.exit(2);
  }

  const results = await pool(todo, opts.concurrency, (a) => processAsset(a, opts));

  const ok = results.filter((r) => r && !r.error);
  const fail = results.filter((r) => r && r.error);

  // 合并已有 manifest
  const manifestPath = path.join(OUT_DIR, "manifest.json");
  let manifest = { generatedAt: null, region: REGION, assets: {} };
  if (fs.existsSync(manifestPath)) {
    try {
      manifest = JSON.parse(fs.readFileSync(manifestPath, "utf8"));
    } catch {
      /* ignore */
    }
  }
  for (const r of ok) manifest.assets[r.id] = r;
  manifest.generatedAt = new Date().toISOString();
  manifest.region = REGION;
  fs.mkdirSync(OUT_DIR, { recursive: true });
  fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 2), "utf8");

  console.log(`\n─────────────────────────────────`);
  console.log(`成功 ${ok.length} 个，失败 ${fail.length} 个`);
  if (fail.length) {
    for (const f of fail) console.log(`  ✗ ${JSON.stringify(f).slice(0, 200)}`);
    process.exitCode = 1;
  }
  console.log(`刷新页面即可看到 Lux3D 生成的道具替换掉占位模型。`);
}

main().catch((e) => {
  console.error("\n致命错误:", e.message || e);
  process.exit(1);
});
