      "sci-fi scanning device, white and slate grey, single object",
    style: "cyberpunk",
    height: 1.45,
  },
  {
    id: "act",
    prompt:
      "An industrial robotic arm with a two finger gripper on a round base, " +
      "white ceramic body with orange accents, clean laboratory robot, single object",
    style: "cyberpunk",
    height: 1.45,
  },
  {
    id: "verify",
    prompt:
      "An ornate brass balance scale with two hanging pans and a central pillar, " +
      "steampunk precision measuring instrument, single object",
    style: "fantasy",
    height: 1.45,
  },
  {
    id: "answer",
    prompt:
      "A circular sci-fi portal gate standing upright on a base, glowing golden ring between two ornate pillars, " +
      "single object",
    style: "fantasy",
    height: 1.45,
  },
];

/* -------------------------------------------------------------------- 工具 */

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function parseArgs(argv) {
  const out = { force: false, dry: false, only: null, concurrency: 2, faceCount: 120000, timeout: 20 * 60 * 1000 };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--force") out.force = true;
    else if (a === "--dry-run") out.dry = true;
    else if (a === "--only") out.only = (argv[++i] || "").split(",").map((s) => s.trim()).filter(Boolean);
    else if (a === "--concurrency") out.concurrency = Math.max(1, Number(argv[++i]) || 1);
    else if (a === "--face-count") out.faceCount = Number(argv[++i]) || 120000;
    else if (a === "--timeout") out.timeout = Number(argv[++i]) * 1000 || out.timeout;
  }
  return out;
}

async function api(pathname, init = {}) {
  const res = await fetch(BASE + pathname, {
    ...init,
    headers: {
      authorization: ***REDACTED***,
      "content-type": "application/json",
      ...(init.headers || {}),
    },
  });
  const text = await res.text();
  let body;
  try {
    body = JSON.parse(text);
  } catch {
    throw new Error(`HTTP ${res.status} 非 JSON 响应: ${text.slice(0, 200)}`);
  }
  if (body.c !== "0") {
    throw new Error(`接口失败 c=${body.c} m=${body.m || ""}`);
  }
  return body.d;
}

async function createTextTo3D(asset, faceCount) {
  return api("/lux3d/v1/generate/text-to-3d/task/create", {
    method: "POST",
    body: JSON.stringify({
      prompt: asset.prompt,
      style: asset.style,
      version: "G1",
      faceCount,
      outputFormat: ["glb"],
      aiPredictSize: true,
    }),
  });
}

async function queryTask(taskId) {
  return api(`/lux3d/v1/generate/task/get?taskid=${encodeURIComponent(taskId)}`);
}

function pickGlb(outputs) {
  for (const o of outputs || []) {
    const c = o && o.content;
    if (typeof c !== "string" || !c || c === "NOT_REQUESTED" || c === "null") continue;
    const clean = c.split("?")[0].toLowerCase();
    if (clean.endsWith(".glb")) return c;
  }
  return null;
}

async function download(url, dest) {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`下载失败 HTTP ${res.status}`);
  const buf = Buffer.from(await res.arrayBuffer());
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.writeFileSync(dest, buf);
  return buf.length;
}

async function waitFor(taskId, timeout) {
  const started = Date.now();
  let last = -1;
  for (;;) {
    if (Date.now() - started > timeout) throw new Error("轮询超时，taskId 已保留，可稍后用 query 复查");
    const d = await queryTask(taskId);
    if (d && d.status !== last) {
      last = d.status;
      const label = { 0: "排队", 1: "生成中", 3: "成功", 4: "失败", 6: "取消" }[d.status] ?? d.status;
      process.stdout.write(`   状态 ${label}\n`);
    }
    if (d && d.status === 3) return d;
    if (d && (d.status === 4 || d.status === 6)) {
      throw new Error(`任务结束但未成功 status=${d.status} ${JSON.stringify(d.outputs || []).slice(0, 200)}`);
    }
    await sleep(10000);
  }
}

/* -------------------------------------------------------------------- 主流程 */

async function processAsset(asset, opts) {
  const dest = path.join(OUT_DIR, `${asset.id}.glb`);
  console.log(`\n▶ ${asset.id}  (style=${asset.style})`);
  console.log(`  ${asset.prompt.slice(0, 90)}…`);

  const taskId = await createTextTo3D(asset, opts.faceCount);
  console.log(`  任务已创建 taskId=${taskId}`);

  const done = await waitFor(taskId, opts.timeout);
  const glbUrl = pickGlb(done.outputs);
  if (!glbUrl) throw new Error(`任务成功但没有 GLB 输出: ${JSON.stringify(done.outputs).slice(0, 300)}`);

  const bytes = await download(glbUrl, dest);
  console.log(`  ✓ 已保存 ${path.relative(ROOT, dest)}  ${(bytes / 1024 / 1024).toFixed(2)} MB`);

  return {
    id: asset.id,
    style: asset.style,
    prompt: asset.prompt,
    taskId,
    height: asset.height,
    bytes,
    file: `models/${asset.id}.glb`,
    generatedAt: new Date().toISOString(),
  };
}

async function pool(items, limit, worker) {
  const results = [];
  let cursor = 0;
  const runners = Array.from({ length: Math.min(limit, items.length) }, async () => {
    for (;;) {
      const i = cursor++;
      if (i >= items.length) return;
      try {
        results[i] = await worker(items[i], i);
      } catch (e) {
        results[i] = { error: String(e.message || e) };
        console.error(`  ✗ ${items[i].id} 失败: ${e.message || e}`);
      }
    }
  });
  await Promise.all(runners);
  return results;
}

async function main() {
  const opts = parseArgs(process.argv.slice(2));

  console.log(`Mind Forge · Lux3D 资产流水线`);
  console.log(`  区域   ${REGION}  (${BASE})`);
  console.log(`  输出   ${path.relative(ROOT, OUT_DIR)}`);

  let todo = ASSETS;
  if (opts.only) todo = todo.filter((a) => opts.only.includes(a.id));
  if (!opts.force) {
    const missing = todo.filter((a) => !fs.existsSync(path.join(OUT_DIR, `${a.id}.glb`)));
    if (missing.length !== todo.length) {
      console.log(`  跳过已存在: ${todo.filter((a) => !missing.includes(a)).map((a) => a.id).join(", ")}`);
    }
    todo = missing;
  }

  if (todo.length === 0) {
    console.log("\n全部资产已存在，加 --force 可重新生成。");
    return;
  }

  console.log(`  计划   ${todo.length} 个: ${todo.map((a) => a.id).join(", ")}`);
  console.log(`  并发   ${opts.concurrency}（免费账户上限 2）`);

  if (opts.dry) {
    console.log("\n--dry-run：不实际调用。");
    return;
  }

  if (!API_KEY) {
    console.error("\n缺少 API Key。请设置 AHOLO_API_KEY 环境变量。");
    process.exit(2);
  }

  const results = await pool(todo, opts.concurrency, (a) => processAsset(a, opts));

  const ok = results.filter((r) => r && !r.error);
  const fail = results.filter((r) => r && r.error);

  // 合并已有 manifest
  const manifestPath = path.join(OUT_DIR, "manifest.json");
  let manifest = { generatedAt: null, region: REGION, assets: {} };
  if (fs.existsSync(manifestPath)) {
    try {
      manifest = JSON.parse(fs.readFileSync(manifestPath, "utf8"));
    } catch {
      /* ignore */
    }
  }
  for (const r of ok) manifest.assets[r.id] = r;
  manifest.generatedAt = new Date().toISOString();
  manifest.region = REGION;
  fs.mkdirSync(OUT_DIR, { recursive: true });
  fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 2), "utf8");

  console.log(`\n─────────────────────────────────`);
  console.log(`成功 ${ok.length} 个，失败 ${fail.length} 个`);
  if (fail.length) {
    for (const f of fail) console.log(`  ✗ ${JSON.stringify(f).slice(0, 200)}`);
    process.exitCode = 1;
  }
  console.log(`刷新页面即可看到 Lux3D 生成的道具替换掉占位模型。`);
}

main().catch((e) => {
  console.error("\n致命错误:", e.message || e);
  process.exit(1);
});
