{"content": "import { useEffect, useRef } from "react";
import * as THREE from "three";
import { useFrame, useThree } from "@react-three/fiber";
import { OrbitControls } from "@react-three/drei";
import { STATIONS } from "../engine/types";
import { useMind } from "../engine/store";

/** 相机球坐标：方位角 az（绕 Y）、俯角 el、半径 r */
const HOME_AZ = Math.PI / 4;
const HOME_EL = 0.56;
const HOME_R = 17.4;

function shortAngle(a: number, b: number) {
  let d = (b - a) % (Math.PI * 2);
  if (d > Math.PI) d -= Math.PI * 2;
  if (d < -Math.PI) d += Math.PI * 2;
  return d;
}

/** 工位在世界里的方位角（球坐标约定） */
function stationAz(angleDeg: number) {
  return Math.PI / 2 - (angleDeg * Math.PI) / 180;
}

function sphericalTo(out: THREE.Vector3, az: number, el: number, r: number) {
  const c = Math.cos(el);
  out.set(Math.sin(az) * c * r, Math.sin(el) * r, Math.cos(az) * c * r);
  return out;
}

export function CameraRig() {
  const { camera } = useThree();
  const focus = useMind((s) => s.focus);
  const seq = useMind((s) => s.seq);
  const viewMode = useMind((s) => s.viewMode);

  const desiredPos = useRef(new THREE.Vector3());
  const desiredTarget = useRef(new THREE.Vector3(0, 1.4, 0));
  const target = useRef(new THREE.Vector3(0, 1.4, 0));
  const initialized = useRef(false);

  useEffect(() => {
    if (focus === "reason") {
      sphericalTo(desiredPos.current, HOME_AZ + 0.1, HOME_EL - 0.04, 14.4);
      desiredTarget.current.set(0, 1.5, 0);
    } else {
      const meta = STATIONS[focus];
      const az = HOME_AZ + shortAngle(HOME_AZ, stationAz(meta.angle)) * 0.55;
      sphericalTo(desiredPos.current, az, HOME_EL, 15.8);
      const rad = (meta.angle * Math.PI) / 180;
      desiredTarget.current.set(Math.cos(rad) * 0.85, 1.35, Math.sin(rad) * 0.85);
    }

    if (!initialized.current) {
      initialized.current = true;
      // 首次进入：从更远处缓推
      sphericalTo(camera.position, HOME_AZ + 0.35, HOME_EL + 0.12, 26);
      camera.lookAt(0, 1.4, 0);
    }
  }, [focus, seq, camera]);

  useFrame((state, dt) => {
    if (viewMode !== "cinematic") return;
    const d = Math.min(dt, 0.05);
    const t = state.clock.elapsedTime;
    const nx = Math.sin(t * 0.29) * 0.12;
    const ny = Math.cos(t * 0.21) * 0.08;

    camera.position.x = THREE.MathUtils.damp(camera.position.x, desiredPos.current.x + nx, 1.35, d);
    camera.position.y = THREE.MathUtils.damp(camera.position.y, desiredPos.current.y + ny, 1.35, d);
    camera.position.z = THREE.MathUtils.damp(camera.position.z, desiredPos.current.z + nx, 1.35, d);

    target.current.x = THREE.MathUtils.damp(target.current.x, desiredTarget.current.x, 1.9, d);
    target.current.y = THREE.MathUtils.damp(target.current.y, desiredTarget.current.y, 1.9, d);
    target.current.z = THREE.MathUtils.damp(target.current.z, desiredTarget.current.z, 1.9, d);

    camera.lookAt(target.current);
  });

  if (viewMode === "orbit") {
    return (
      <OrbitControls
        makeDefault
        enablePan={false}
        minDistance={8}
        maxDistance={30}
        minPolarAngle={0.2}
        maxPolarAngle={Math.PI / 2.1}
        target={[0, 1.3, 0]}
        enableDamping
        dampingFactor={0.08}
      />
    );
  }
  return null;
}
