{"content": "const task = await taskSpace("mindforge 3d demo");
const page = task.page("p1");
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const win = await page.cdp("Browser.getWindowForTarget", {});
await page.cdp("Browser.setWindowBounds", { windowId: win.windowId, bounds: { windowState: "normal" } });
await page.goto("http://127.0.0.1:5178/");
await page.cdp("Emulation.setDeviceMetricsOverride", {
  width: 1640,
  height: 940,
  deviceScaleFactor: 1,
  mobile: false,
});
await sleep(3000);

const shots = [
  [1400, "perceive"],
  [15500, "act"],
  [24000, "reason"],
  [40500, "answer"],
];

for (const [t, name] of shots) {
  await page.evaluate((tt) => {
    const s = window.__mind.getState();
    s.pause();
    s.seek(tt);
  }, t);
  await sleep(2600);
  await page.screenshot({ path: `C:/work/ego/mindforge/frame-${name}.png` });
  console.log("shot", name);
}
", "file_path": "C:\work\ego\mindforge\round-05.mjs"}

