{"content": "const task = await taskSpace("mindforge 3d demo");
const page = task.page("p1");
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

await page.goto("http://127.0.0.1:5178/");
await page.cdp("Emulation.setDeviceMetricsOverride", {
  width: 1640,
  height: 940,
  deviceScaleFactor: 1,
  mobile: false,
});
try {
  await page.cdp("Page.bringToFront");
  console.log("bringToFront ok");
} catch (e) {
  console.log("bringToFront:", e.message);
}
await sleep(1500);

const fps = await page.evaluate(async () => {
  const vis = document.visibilityState;
  let n = 0;
  const t0 = performance.now();
  await new Promise((res) => {
    const tick = () => {
      n++;
      if (performance.now() - t0 > 1000) res();
      else requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  });
  return { vis, fps: n };
});
console.log("fps:", JSON.stringify(fps));

await page.evaluate(() => {
  const s = window.__mind.getState();
  s.pause();
  s.seek(40500);
});
await sleep(4000);
const d = await page.evaluate(() => {
  const c = window.__cam;
  return {
    pos: [+c.position.x.toFixed(2), +c.position.y.toFixed(2), +c.position.z.toFixed(2)],
    dist: +Math.hypot(c.position.x, c.position.y - 1.4, c.position.z).toFixed(2),
  };
});
console.log("answer cam:", JSON.stringify(d));
", "file_path": "C:\work\ego\mindforge\round-07.mjs"}

