/* ------------------------------------------------------------ 进度环（3D 进度条） */

function ProgressRing() {
  const mat = useMemo(
    () =>
      new THREE.ShaderMaterial({
        uniforms: {
          uProgress: { value: 0 },
          uColor: { value: new THREE.Color("#3fe3ff") },
        },
        vertexShader: /* glsl */ `
          varying float vAng;
          void main() {
            vAng = atan(position.y, position.x);
            gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
          }
        `,
        fragmentShader: /* glsl */ `
          uniform float uProgress;
          uniform vec3 uColor;
          varying float vAng;
          void main() {
            float a = fract((vAng + 3.14159265) / 6.28318531);
            if (a > uProgress) discard;
            float head = smoothstep(0.06, 0.0, uProgress - a);
            gl_FragColor = vec4(uColor * (1.6 + head * 2.4), 0.55 + head * 0.45);
          }
        `,
        transparent: true,
        depthWrite: false,
        side: THREE.DoubleSide,
        blending: THREE.AdditiveBlending,
        toneMapped: false,
      }),
    [],
  );

  useFrame(() => {
    const s = mind();
    mat.uniforms.uProgress.value = s.totalMs > 0 ? Math.min(1, s.playhead / s.totalMs) : 0;
  });

  return (
    <mesh position={[0, 0.05, 0]} rotation={[-Math.PI / 2, 0, 0]} material={mat}>
      <ringGeometry args={[5.34, 5.42, 256]} />
    </mesh>
  );
