  glow?: { color: string; base: number; peak: number };
  station?: StationId;
}) {
  const { scene } = useGLTF(url);
  const grp = useRef<THREE.Group>(null!);

  const prepared = useMemo(() => {
    const root = scene.clone(true);
    root.updateWorldMatrix(true, true);
    const box = new THREE.Box3().setFromObject(root);
    const size = box.getSize(new THREE.Vector3());
    const center = box.getCenter(new THREE.Vector3());
    const s = height / Math.max(size.y, 1e-4);

    // 收集材质，供发光脉冲使用
    const materials: THREE.MeshStandardMaterial[] = [];
    root.traverse((o) => {
      const mesh = o as THREE.Mesh;
      if (!mesh.isMesh) return;
      const m = mesh.material;
      for (const mm of Array.isArray(m) ? m : [m]) {
        const std = mm as THREE.MeshStandardMaterial;
        if (std && (std as unknown as { isMeshStandardMaterial?: boolean }).isMeshStandardMaterial) {
          materials.push(std);
          if (glow) {
            std.emissive = new THREE.Color(glow.color);
            std.emissiveIntensity = glow.base;
          }
        }
      }
    });

    return { root, s, center, minY: box.min.y, materials };
  }, [scene, height, glow]);

  useFrame((st) => {
    if (grp.current) grp.current.rotation.y = st.clock.elapsedTime * 0.22;
    if (glow && station) {
      const e = energy(station);
      const v = glow.base + e * glow.peak;
      for (const m of prepared.materials) m.emissiveIntensity = v;
    }
  });

  return (
    <group ref={grp}>
      <primitive
        object={prepared.root}
        scale={prepared.s}
        position={[-prepared.center.x * prepared.s, -prepared.minY * prepared.s + 0.14, -prepared.center.z * prepared.s]}
      />
    </group>
  );
