{"content": "const task = await taskSpace("mindforge 3d demo");
const page = task.page("p1");
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const win = await page.cdp("Browser.getWindowForTarget", {});
await page.cdp("Browser.setWindowBounds", {
  windowId: win.windowId,
  bounds: { windowState: "normal" },
});

await page.goto("http://127.0.0.1:5178/");
await page.cdp("Emulation.setDeviceMetricsOverride", {
  width: 1640,
  height: 940,
  deviceScaleFactor: 1,
  mobile: false,
});
await sleep(4000);

const shots = [
  [1500, "perceive"],
  [3300, "reason"],
  [15100, "act"],
  [27400, "verify"],
  [39600, "answer"],
];

for (const [t, name] of shots) {
  await page.evaluate((tt) => {
    const s = window.__mind.getState();
    s.pause();
    s.seek(tt);
  }, t);
  await sleep(2400);
  await page.screenshot({ path: `C:/work/ego/mindforge/g-${name}.png` });
  console.log("shot", name);
}

// 回到起点，播放几秒后的自然状态
await page.evaluate(() => {
  const s = window.__mind.getState();
  s.reset();
  s.play();
});
await sleep(6500);
await page.screenshot({ path: "C:/work/ego/mindforge/g-hero.png" });
console.log("shot hero");
", "file_path": "C:\work\ego\mindforge\round-09.mjs"}

