const OUT_DIR = path.join(ROOT, "public", "models");

const REGION = process.env.LUX3D_REGION === "global" ? "global" : "cn";
const BASE = REGION === "global" ? "https://api.aholo.ai/global" : "https://api.aholo3d.cn";
const KEY = ***REDACTED***.env.AHOLO_API_KEY || process.env.LUX3D_API_KEY || "";

const STATUS = { 0: "排队", 1: "运行中", 3: "成功", 4: "失败", 6: "已取消" };

async function api(p) {
  const r = await fetch(BASE + p, { headers: { authorization: KEY } });
  const j = await r.json();
  if (j.c !== "0") throw new Error(`接口失败 c=${j.c} m=${j.m || ""}`);
  return j.d;
}

function pickGlb(outputs = []) {
  for (const o of outputs) {
    const c = o?.content;
    if (typeof c !== "string" || !c || c === "NOT_REQUESTED" || c === "null") continue;
    if (c.split("?")[0].toLowerCase().endsWith(".glb")) return c;
  }
  return null;
}

const args = process.argv.slice(2);

if (!KEY) {
  console.error("缺少 API Key：请设置 AHOLO_API_KEY");
  process.exit(2);
}

if (args[0] === "--list" || args.length === 0) {
  const d = await api("/lux3d/v1/generate/task/list?page=1&pagesize=30");
  console.log("taskId    状态      创建时间              类型");
  for (const it of d.items) {
    console.log(
      String(it.taskId).padEnd(10),
      (STATUS[it.status] ?? it.status).padEnd(8),
      new Date(it.created).toLocaleString("zh-CN").padEnd(22),
      it.taskType,
    );
  }
  console.log("\n补下载：node scripts/fetch-task.mjs <taskId> <道具id>");
  process.exit(0);
}

const [taskId, id = `task-${taskId}`] = args;
const d = await api(`/lux3d/v1/generate/task/get?taskid=${encodeURIComponent(taskId)}`);
console.log(`任务 ${taskId} 状态：${STATUS[d.status] ?? d.status}`);

if (d.status !== 3) {
  console.error("任务尚未成功，无法下载结果。稍后再试；不要重新提交任务。");
  process.exit(1);
}

const url = pickGlb(d.outputs);
if (!url) {
  console.error("没有 GLB 产物：", JSON.stringify(d.outputs).slice(0, 300));
  process.exit(1);
}

const res = await fetch(url);
if (!res.ok) {
  console.error(`下载失败 HTTP ${res.status}（产物 URL 可能已过期，需重新生成）`);
  process.exit(1);
}
const buf = Buffer.from(await res.arrayBuffer());
fs.mkdirSync(OUT_DIR, { recursive: true });
const dest = path.join(OUT_DIR, `${id}.glb`);
fs.writeFileSync(dest, buf);
console.log(`✓ 已保存 ${path.relative(ROOT, dest)}  ${(buf.length / 1024 / 1024).toFixed(2)} MB`);
", "file_path": "C:\work\mindforge\scripts\fetch-task.mjs"}

