    canvas: !!document.querySelector("canvas"),
    events: s.trace.length,
    totalMs: s.totalMs,
    playing: s.playing,
    labels: document.querySelectorAll(".st-label").length,
    rows: document.querySelectorAll(".row").length,
  };
});
console.log("state:", JSON.stringify(state));
await sleep(5000);
const st2 = await page.evaluate(() => ({ playhead: Math.round(window.__mind.getState().playhead) }));
console.log("after 5s playhead:", st2.playhead);
