{"command": "$js = @'
import fs from "node:fs";
const t = JSON.parse(fs.readFileSync("C:/work/mindforge/docs/agent-run/trace.json", "utf8"));
const n = t.nodes;
const kinds = {};
for (const x of n) kinds[x.kind] = (kinds[x.kind] || 0) + 1;
const tokens = n.reduce((a, x) => a + (x.tokens || 0), 0);
const tools = n.filter(x => x.kind === "tool").length;
const failed = n.filter(x => x.status === "failed").length;
const end = Math.max(...n.map(x => x.t + x.dur));
const ids = new Set(n.map(x => x.id));
const badEdges = t.edges.filter(e => !ids.has(e.from) || !ids.has(e.to));
console.log("JSON 有效 ✓");
console.log("节点", n.length, "| 工具", tools, "| 失败", failed, "| token", tokens, "| 结束", end + "ms");
console.log("类型分布", JSON.stringify(kinds));
console.log("非法边", badEdges.length);
console.log("时间顺序单调:", n.every((x, i) => i === 0 || x.t >= n[i-1].t));
'@
$f = Join-Path $env:TEMP "v1.mjs"; Set-Content -Path $f -Value $js -Encoding UTF8; node $f 2>&1", "description": "Validate trace JSON and recompute stats", "timeoutMs": 60000}

