import fs from "node:fs";
import zlib from "node:zlib";

const f = "C:\\Users\\36322\\.dsh\\sessions\\--D-Ash-Work--\\session-10167f6f-37c9-4ddc-8c8b-860c95ee88bf\\session.v4.jsonl.zstd";
