const lines = out.split("\n").filter(Boolean);
console.log("解压后行数:", lines.length, "| 字节:", out.length);
const types = {};
const samples = {};
for (const l of lines) {
  try {
    const o = JSON.parse(l);
    const t = o.type || o.kind || o.event || "?";
    types[t] = (types[t] || 0) + 1;
    if (!samples[t]) samples[t] = l.slice(0, 400);
  } catch { types["UNPARSED"] = (types["UNPARSED"]||0)+1; }
}
console.log("记录类型:", JSON.stringify(types, null, 1));
for (const [t, s] of Object.entries(samples)) console.log("\n--- " + t + " ---\n" + s);
'@
$f = Join-Path $env:TEMP "dsh1.mjs"; Set-Content -Path $f -Value $js -Encoding UTF8; node $f 2>&1", "description": "Decode a DSH session file and inspect record types", "timeoutMs": 60000}

