const magic = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);
const offs = [];
for (let i = 0; i + 3 < buf.length; i++) {
  if (buf[i] === 0x28 && buf[i+1] === 0xb5 && buf[i+2] === 0x2f && buf[i+3] === 0xfd) offs.push(i);
}
console.log("frame 数量:", offs.length, "| 首偏移:", offs.slice(0, 5));

let total = "";
let okFrames = 0, failFrames = 0;
for (let k = 0; k < offs.length; k++) {
  const start = offs[k];
  const end = k + 1 < offs.length ? offs[k + 1] : buf.length;
  try {
    total += zlib.zstdDecompressSync(buf.subarray(start, end)).toString("utf8");
    okFrames++;
  } catch { failFrames++; }
}
