/* ---------------------------------------------------------------- 原始记录 */

export interface RawRecord {
  type: string;
  seq: number;
  time: number;
  data?: Record<string, any>;
}

/* ---------------------------------------------------------------- 小人状态 */

export type AgentState = "in" | "work" | "out" | "kick";

export interface AgentView {
  callId: string;
  tool: string;
  slot: number;
  state: AgentState;
  bornAt: number;
  endAt?: number;
  isError?: boolean;
  label: string;
}

export const SLOT_COUNT = 7;

/* ------------------------------------------------------------ 工具 → 道具 */

export type PropKind = "search" | "exec" | "file" | "deliver" | "misc";

export function propOf(tool: string): PropKind {
  if (/search|research|fetch|weather/i.test(tool)) return "search";
  if (/pwsh|node|python|job_/i.test(tool)) return "exec";
  if (/write|edit|read|grep|glob/i.test(tool)) return "file";
  if (/present|deliver/i.test(tool)) return "deliver";
  return "misc";
}

/** 工具名 → 一句人话，给 HUD 用 */
export function toolLabel(tool: string): string {
  const map: Record<string, string> = {
    web_search: "上网查",
    advanced_search: "上网查",
    research: "做调研",
    web_fetch: "读网页",
    domain_search: "查资料",
    pwsh: "开机器",
    write: "写文件",
    edit: "改文件",
    read: "翻文件",
    read_image: "看图片",
    grep: "搜索代码",
    glob: "找文件",
    todo_write: "列计划",
    job_output: "等结果",
    job_kill: "停任务",
    present: "交付",
    skill: "翻手册",
    ask_user_question: "问用户",
  };
  return map[tool] || tool;
}

