  connected: boolean;
  mode: "live" | "replay";
  session: string | null;

  agents: AgentView[];
  turn: number;
  tokens: number;
  toolCount: number;
  errorCount: number;
  bubble: Bubble | null;
  phase: Phase;
  approvalReason: string | null;
  lastEventAt: number;
  log: LogLine[];

  apply: (rec: RawRecord) => void;
  gc: (now: number) => void;
  setConnected: (v: boolean) => void;
  setMode: (m: "live" | "replay") => void;
  reset: () => void;
}

function nextSlot(agents: AgentView[]): number {
  const used = new Set(agents.filter((a) => a.state === "in" || a.state === "work").map((a) => a.slot));
  for (let i = 0; i < SLOT_COUNT; i++) if (!used.has(i)) return i;
  return Math.floor(Math.random() * SLOT_COUNT);
