{"content": "import { useOffice, type RawRecord } from "./model";

const SSE_URL = "http://127.0.0.1:8787/events";

let started = false;
let es: EventSource | null = null;
let timers: number[] = [];

/** 回放速度：真实会话可能几十分钟，压到 1~2 分钟 */
const REPLAY_SPEED = 30;

function clearTimers() {
  for (const t of timers) window.clearTimeout(t);
  timers = [];
}

export function startFeed() {
  if (started) return;
  started = true;

  const forced = new URLSearchParams(location.search).get("source");
  if (forced === "replay") {
    startReplay();
    return;
  }
  startLive();
}

function startLive() {
  const store = useOffice.getState();
  store.setMode("live");

  try {
    es = new EventSource(SSE_URL);
  } catch {
    startReplay();
    return;
  }

  es.addEventListener("open", () => {
    useOffice.getState().setConnected(true);
    useOffice.getState().setMode("live");
  });

  es.addEventListener("reset", () => {
    useOffice.getState().reset();
  });

  es.addEventListener("message", (ev) => {
    try {
      const rec = JSON.parse((ev as MessageEvent).data) as RawRecord;
      useOffice.getState().apply(rec);
    } catch {
      /* 坏的帧，忽略 */
    }
  });

  es.addEventListener("error", () => {
    useOffice.getState().setConnected(false);
    // 本地没开 tailer → 退回到静态回放
    es?.close();
    es = null;
    startReplay();
  });
}

async function startReplay() {
  useOffice.getState().setMode("replay");
  clearTimers();

  let text = "";
  try {
    const res = await fetch(`${import.meta.env.BASE_URL}replay.jsonl`, { cache: "no-store" });
    if (!res.ok) throw new Error(String(res.status));
    text = await res.text();
  } catch {
    // 没有回放文件也不崩，显示空场景
    return;
  }

  const records: RawRecord[] = [];
  for (const line of text.split("\n")) {
    const s = line.trim();
    if (!s) continue;
    try {
      const r = JSON.parse(s);
      if (r.type !== "export/meta") records.push(r);
    } catch {
      /* ignore */
    }
  }
  if (!records.length) return;

  const play = () => {
    useOffice.getState().reset();
    useOffice.getState().setConnected(true);
    const t0 = records[0].time ?? 0;
    for (const r of records) {
      const at = Math.max(0, ((r.time ?? t0) - t0) / REPLAY_SPEED);
      const timer = window.setTimeout(() => useOffice.getState().apply(r), at);
      timers.push(timer);
    }
    const last = ((records[records.length - 1].time ?? t0) - t0) / REPLAY_SPEED;
    // 播完歇一会儿再来一遍
    timers.push(window.setTimeout(play, last + 9000));
  };

  play();
}
