}

/* ---------------------------------------------------------------- 主角 */

function Protagonist() {
  const grp = useRef<THREE.Group>(null!);
  const body = useRef<THREE.Mesh>(null!);
  const head = useRef<THREE.Mesh>(null!);
  const headMat = useRef<THREE.MeshStandardMaterial>(null!);
  const phase = useOffice((s) => s.phase);
  const bubble = useOffice((s) => s.bubble);
  const errorCount = useOffice((s) => s.errorCount);

  const errAt = useRef(0);
  useEffect(() => {
    if (errorCount > 0) errAt.current = Date.now();
  }, [errorCount]);

  const pos = useRef(new THREE.Vector3().copy(DESK_BACK));
  const target = useRef(new THREE.Vector3().copy(DESK_BACK));
  const rotY = useRef(0);
  const targetRot = useRef(0);

  useFrame((state, dt) => {
    const now = Date.now();
    const t = state.clock.elapsedTime;
    const d = Math.min(dt, 0.05);

    if (phase === "approval") {
      target.current.copy(APPROVAL_SPOT);
      targetRot.current = 0.45; // 面向镜头
    } else {
      target.current.copy(DESK_BACK);
      targetRot.current = 0;
    }

    pos.current.x = THREE.MathUtils.damp(pos.current.x, target.current.x, 2.4, d);
    pos.current.z = THREE.MathUtils.damp(pos.current.z, target.current.z, 2.4, d);
    rotY.current = THREE.MathUtils.damp(rotY.current, targetRot.current, 3, d);

    if (grp.current) {
      grp.current.position.set(pos.current.x, 0, pos.current.z);
      grp.current.rotation.y = rotY.current;
    }

    // 打字时的上下抖动 / 待机时的呼吸
    const working = phase === "working";
    const bob = working ? Math.abs(Math.sin(t * 9)) * 0.045 : Math.sin(t * 1.6) * 0.018;
    if (body.current) body.current.position.y = 0.42 + bob;
    if (head.current) {
      head.current.position.y = 0.98 + bob;
      head.current.rotation.z = working ? Math.sin(t * 9) * 0.03 : Math.sin(t * 0.9) * 0.06;
    }

    // 刚出错 → 脸红
    const since = (now - errAt.current) / 1000;
    const red = errAt.current && since < 4 ? Math.max(0, 1 - since / 4) : 0;
    if (headMat.current) {
      headMat.current.color.setRGB(0.93 + red * 0.07, 0.79 - red * 0.45, 0.68 - red * 0.42);
      headMat.current.emissive.setRGB(red * 0.35, 0, 0);
      headMat.current.emissiveIntensity = red;
    }
  });

  const showBubble = bubble && Date.now() - bubble.at < 6000;

  return (
    <group ref={grp} position={[DESK_BACK.x, 0, DESK_BACK.z]}>
      <mesh ref={body} position={[0, 0.42, 0]}>
        <boxGeometry args={[0.62, 0.72, 0.4]} />
        <meshStandardMaterial color="#43506b" roughness={0.8} />
      </mesh>
      <mesh ref={head} position={[0, 0.98, 0]}>
        <boxGeometry args={[0.46, 0.44, 0.44]} />
        <meshStandardMaterial ref={headMat} color="#eec9ad" roughness={0.75} />
      </mesh>
      {/* 眼睛 */}
      <mesh position={[-0.1, 1.0, 0.23]}>
        <boxGeometry args={[0.07, 0.07, 0.03]} />
        <meshBasicMaterial color="#1a1a22" />
      </mesh>
      <mesh position={[0.1, 1.0, 0.23]}>
        <boxGeometry args={[0.07, 0.07, 0.03]} />
        <meshBasicMaterial color="#1a1a22" />
      </mesh>

      {showBubble && (
        <Html position={[0, 1.85, 0]} center distanceFactor={9} zIndexRange={[6, 0]}>
          <div className="bubble">{bubble!.text}</div>
        </Html>
      )}
    </group>
  );
}

/* ---------------------------------------------------------------- 小人 */

function Actor({ agent }: { agent: AgentView }) {
  const grp = useRef<THREE.Group>(null!);
  const hand = useRef<THREE.Mesh>(null!);

  const slotPos = useMemo(() => {
    const [x, z] = SLOTS[agent.slot % SLOTS.length];
    return new THREE.Vector3(x, 0, z);
  }, [agent.slot]);

  const ctrlIn = useMemo(
    () => new THREE.Vector3((DOOR.x + slotPos.x) / 2 - 0.5, 0, (DOOR.z + slotPos.z) / 2 + 1.2),
    [slotPos],
  );
  const tmp = useMemo(() => new THREE.Vector3(), []);
  const color = PALETTE[agent.slot % PALETTE.length];
  const propColor = PROP_COLOR[propOf(agent.tool)] || "#9aa4b2";

  useFrame((state) => {
    const now = Date.now();
    const t = state.clock.elapsedTime;
    if (!grp.current) return;

    const scaleIn = Math.min(1, (now - agent.bornAt) / 180);

    if (agent.state === "in" || agent.state === "work") {
      const p = Math.min(1, (now - agent.bornAt) / 950);
      bezier(DOOR, ctrlIn, slotPos, 1 - Math.pow(1 - p, 3), tmp);
      tmp.y = Math.abs(Math.sin(p * Math.PI * 4)) * 0.05;
      grp.current.position.copy(tmp);
      grp.current.rotation.y = p < 1 ? Math.atan2(slotPos.x - DOOR.x, slotPos.z - DOOR.z) : Math.PI;
      if (p >= 1) {
        grp.current.position.y = Math.abs(Math.sin(t * 7)) * 0.04;
        grp.current.rotation.y = Math.PI + Math.sin(t * 2) * 0.15;
      }
    } else if (agent.state === "out") {
      const p = Math.min(1, (now - (agent.endAt ?? now)) / 900);
      bezier(slotPos, ctrlIn, DOOR, p, tmp);
      tmp.y = Math.abs(Math.sin(p * Math.PI * 4)) * 0.05;
      grp.current.position.copy(tmp);
      grp.current.rotation.y = Math.atan2(DOOR.x - slotPos.x, DOOR.z - slotPos.z);
      grp.current.scale.setScalar(Math.max(0.001, 1 - Math.max(0, p - 0.85) / 0.15));
      if (p >= 1) grp.current.visible = false;
    } else {
      // 被踢飞
      const p = Math.min(1, (now - (agent.endAt ?? now)) / 780);
      tmp.lerpVectors(slotPos, DOOR_OUT, p);
      tmp.y = Math.sin(p * Math.PI) * 1.5;
      grp.current.position.copy(tmp);
      grp.current.rotation.y += 0.35;
      grp.current.rotation.z = p * 3.2;
    }

    const s = 0.52 * scaleIn;
    if (agent.state !== "out") grp.current.scale.setScalar(s);
    if (hand.current) hand.current.position.y = 0.34 + Math.sin(t * 12) * 0.03;
  });

  return (
    <group ref={grp} scale={0.001}>
      <mesh position={[0, 0.23, 0]}>
        <boxGeometry args={[0.34, 0.44, 0.26]} />
        <meshStandardMaterial color={color} roughness={0.75} />
      </mesh>
      <mesh position={[0, 0.55, 0]}>
        <boxGeometry args={[0.3, 0.28, 0.28]} />
        <meshStandardMaterial color="#f0d3b8" roughness={0.8} />
      </mesh>
      <mesh ref={hand} position={[0.19, 0.34, 0.06]}>
        <boxGeometry args={[0.12, 0.16, 0.1]} />
        <meshStandardMaterial color={propColor} emissive={propColor} emissiveIntensity={0.35} />
      </mesh>
    </group>
  );
}

function Agents() {
  const agents = useOffice((s) => s.agents);
  const gc = useOffice((s) => s.gc);
  useFrame(() => gc(Date.now()));
  return (
    <>
      {agents.map((a) => (
        <Actor key={a.callId} agent={a} />
      ))}
    </>
  );
}

/* ---------------------------------------------------------------- 标示 */

function HangingProps() {
  const agents = useOffice((s) => s.agents);
  const tokens = useOffice((s) => s.tokens);
  const toolCount = useOffice((s) => s.toolCount);
  const active = agents.filter((a) => a.state === "in" || a.state === "work").length;

  return (
    <>
      {/* 门框计数器 */}
      <Html position={[DOOR.x + 0.3, 2.65, DOOR.z]} center distanceFactor={11} zIndexRange={[6, 0]}>
        <div className={`counter ${active > 0 ? "on" : ""}`}>
          <span className="counter-n">{active}</span>
          <span className="counter-k">在跑</span>
        </div>
      </Html>

      {/* 墙上大屏 */}
      <Html position={[4.6, 2.5, -5.3]} center distanceFactor={13} zIndexRange={[6, 0]}>
        <div className="screen">
          <div className="screen-row">
            <span>token</span>
            <b>{tokens.toLocaleString()}</b>
          </div>
          <div className="screen-row">
            <span>工具</span>
            <b>{toolCount}</b>
          </div>
          <div className="screen-row">
            <span>并行</span>
            <b>{active}</b>
          </div>
        </div>
      </Html>
    </>
  );
}

/* ---------------------------------------------------------------- 相机 */

function CameraRig() {
  const { camera } = useThree();
  const phase = useOffice((s) => s.phase);
  const target = useRef(new THREE.Vector3(0, 1.0, -0.6));

  useEffect(() => {
    camera.position.set(8.6, 6.6, 12.2);
    camera.lookAt(0, 1.0, -0.6);
  }, [camera]);

  useFrame((state, dt) => {
    const d = Math.min(dt, 0.05);
    const t = state.clock.elapsedTime;
    // 轻微呼吸，别让画面死掉
    const sway = Math.sin(t * 0.18) * 0.5;
    const want = phase === "approval" ? new THREE.Vector3(-1.2, 1.2, -0.4) : new THREE.Vector3(0, 1.0, -0.6);
    target.current.x = THREE.MathUtils.damp(target.current.x, want.x, 1.2, d);
    target.current.y = THREE.MathUtils.damp(target.current.y, want.y, 1.2, d);
    target.current.z = THREE.MathUtils.damp(target.current.z, want.z, 1.2, d);
    camera.position.x = THREE.MathUtils.damp(camera.position.x, 8.6 + sway, 0.8, d);
    camera.lookAt(target.current);
  });

  return null;
}

/* ---------------------------------------------------------------- 场景 */

export function Scene() {
  return (
    <Canvas
      dpr={[1, 1.4]}
      gl={{ antialias: true, powerPreference: "high-performance" }}
      camera={{ position: [8.6, 6.6, 12.2], fov: 38, near: 0.5, far: 80 }}
      onCreated={({ gl }) => {
        gl.toneMapping = THREE.ACESFilmicToneMapping;
        gl.toneMappingExposure = 1.0;
      }}
    >
      <color attach="background" args={["#0a0d14"]} />
      <fog attach="fog" args={["#0a0d14", 18, 46]} />
      <Room />
      <Protagonist />
      <Agents />
      <HangingProps />
      <CameraRig />
    </Canvas>
  );
}
