  const log = useOffice((s) => s.log);
  const agents = useOffice((s) => s.agents);

  const active = agents.filter((a) => a.state === "in" || a.state === "work").length;

  return (
    <div className="hud">
      <header className="top">
        <div className="brand">
          <div className="logo" />
          <div>
            <h1>AI 打工人</h1>
            <p>智能体工作过程 · 3D 可视化</p>
          </div>
        </div>
        <div className="meta">
          <span className={`dot ${connected ? "on" : ""}`} />
