  padding: 18px 24px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
}

.logo {
  width: 34px;
  height: 34px;
  border-radius: 9px;
  background: linear-gradient(140deg, #f0a35e, #e8574a);
  box-shadow: 0 0 22px -6px #e8574a;
}

.brand h1 {
  margin: 0;
  font-size: 17px;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.brand p {
  margin: 3px 0 0;
  font-size: 11px;
  color: var(--muted);
}

.meta {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 11.5px;
  color: var(--muted);
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 7px 13px;
  backdrop-filter: blur(10px);
}

.dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #55607a;
}

.dot.on {
  background: #4ade80;
  box-shadow: 0 0 10px #4ade80;
  animation: pulse 1.8s ease-in-out infinite;
}

@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.35;
  }
}

.mode {
  color: #b9c8dd;
}

.session {
  font-family: var(--mono);
  font-size: 10px;
  color: #55607a;
  max-width: 220px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ------------------------------------------------------------------ 面板 */

.panel {
  position: absolute;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 14px;
  backdrop-filter: blur(14px);
  box-shadow: 0 20px 50px -30px #000;
}

.log-panel {
  left: 24px;
  top: 92px;
  width: 320px;
  bottom: 78px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 15px 10px;
  border-bottom: 1px solid var(--line);
  font-size: 11.5px;
  letter-spacing: 0.14em;
  color: #9fb0c8;
}

.turn {
  font-family: var(--mono);
  font-size: 10.5px;
  color: #5d6a80;
  letter-spacing: 0;
}

.log-list {
  flex: 1;
  overflow-y: auto;
  padding: 8px;
  scrollbar-width: thin;
  scrollbar-color: rgba(140, 170, 210, 0.25) transparent;
}

.log-list::-webkit-scrollbar {
  width: 6px;
}

.log-list::-webkit-scrollbar-thumb {
  background: rgba(140, 170, 210, 0.22);
  border-radius: 99px;
}

.empty {
  padding: 30px 12px;
  text-align: center;
  color: #4d5871;
  font-size: 12px;
}

.log-row {
  display: flex;
  gap: 8px;
  align-items: flex-start;
  padding: 6px 8px;
  border-radius: 8px;
}

.log-row:first-child {
  background: rgba(120, 160, 220, 0.07);
}

.log-kind {
  flex: 0 0 auto;
  font-size: 9.5px;
  border: 1px solid;
  border-radius: 4px;
  padding: 1px 5px;
  margin-top: 2px;
  letter-spacing: 0.04em;
}

.log-text {
  font-size: 12px;
  line-height: 1.45;
  color: #cfdaea;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

/* ---------------------------------------------------------------- 统计 */

.stat-panel {
  right: 24px;
  top: 92px;
  width: 190px;
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.stat {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.stat .k {
  font-size: 11px;
  color: var(--muted);
}

.stat .v {
  font-family: var(--mono);
  font-size: 17px;
  color: #e6eefc;
}

.stat .v.danger {
  color: #ff8080;
}

.phase {
  margin-top: 4px;
  text-align: center;
  font-size: 11.5px;
  padding: 7px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--line);
  color: #b9c8dd;
}

.phase-working {
  color: #86efac;
  border-color: rgba(134, 239, 172, 0.3);
}

.phase-approval {
  color: #f9a8d4;
  border-color: rgba(249, 168, 212, 0.4);
  animation: pulse 1.2s ease-in-out infinite;
}

.phase-done {
  color: #fcd34d;
}

/* ---------------------------------------------------------------- 审批 */

.approval {
  position: absolute;
  left: 50%;
  bottom: 110px;
  transform: translateX(-50%);
  text-align: center;
  padding: 16px 26px;
  border-radius: 14px;
  background: rgba(40, 14, 30, 0.82);
  border: 1px solid rgba(249, 168, 212, 0.42);
  box-shadow: 0 0 50px -16px #f472b6;
  animation: rise 0.4s ease-out both;
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translate(-50%, 10px);
  }
  to {
    opacity: 1;
    transform: translate(-50%, 0);
  }
}

.approval-title {
  font-size: 15px;
  font-weight: 700;
  color: #fbcfe8;
}

.approval-reason {
  margin-top: 6px;
  font-size: 12px;
  color: #d3b7cb;
  max-width: 460px;
  line-height: 1.5;
}

.approval-hint {
  margin-top: 8px;
  font-size: 10.5px;
  color: #9b7f92;
  letter-spacing: 0.04em;
}

/* ---------------------------------------------------------------- 页脚 */

.foot {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 16px;
  text-align: center;
  font-size: 10.5px;
  color: #46516a;
  letter-spacing: 0.04em;
}

.foot .sep {
  margin: 0 8px;
}

/* ------------------------------------------------------- 3D 里的 HTML 层 */

.bubble {
  max-width: 190px;
  padding: 7px 11px;
  border-radius: 11px;
  background: rgba(250, 250, 252, 0.96);
  color: #1b2130;
  font-size: 11px;
  line-height: 1.45;
  box-shadow: 0 8px 24px -8px rgba(0, 0, 0, 0.7);
  position: relative;
}

.bubble::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -6px;
  transform: translateX(-50%);
  width: 0;
  height: 0;
  border-left: 6px solid transparent;
  border-right: 6px solid transparent;
  border-top: 7px solid rgba(250, 250, 252, 0.96);
}

.counter {
  display: flex;
  align-items: baseline;
  gap: 5px;
  padding: 3px 9px;
  border-radius: 8px;
  background: rgba(10, 14, 22, 0.9);
  border: 1px solid rgba(120, 160, 210, 0.28);
  font-family: var(--mono);
  transition: all 0.2s;
}

.counter.on {
  border-color: rgba(74, 222, 128, 0.6);
  box-shadow: 0 0 18px -4px rgba(74, 222, 128, 0.7);
}

.counter-n {
  font-size: 17px;
  color: #e6eefc;
  font-weight: 700;
}

.counter.on .counter-n {
  color: #86efac;
}

.counter-k {
  font-size: 9px;
  color: #6b778f;
}

.screen {
  width: 200px;
  padding: 10px 12px;
  border-radius: 8px;
  background: rgba(10, 16, 26, 0.9);
  border: 1px solid rgba(120, 160, 210, 0.2);
  font-family: var(--mono);
}

.screen-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 11px;
  color: #7f8da5;
  padding: 2px 0;
}

.screen-row b {
  font-size: 14px;
  color: #9fe8ff;
}
