{"content": "const task = await taskSpace("agent-office");
const page = task.page("p1");
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const win = await page.cdp("Browser.getWindowForTarget", {});
await page.cdp("Browser.setWindowBounds", { windowId: win.windowId, bounds: { windowState: "normal" } });

await page.goto("http://127.0.0.1:5180/");
await page.cdp("Emulation.setDeviceMetricsOverride", {
  width: 1600,
  height: 900,
  deviceScaleFactor: 1,
  mobile: false,
});
await sleep(5000);

const st = await page.evaluate(() => {
  const s = window.__office?.getState?.();
  return s
    ? {
        connected: s.connected,
        mode: s.mode,
        agents: s.agents.length,
        working: s.agents.filter((a) => a.state === "in" || a.state === "work").length,
        log: s.log.length,
        tokens: s.tokens,
        tools: s.toolCount,
        turn: s.turn,
        phase: s.phase,
      }
    : { error: "no store" };
});
console.log("state:", JSON.stringify(st));

await page.screenshot({ path: "C:/work/ego/mindforge/office-01.png" });
console.log("shot ok");
