{"content": "const task = await taskSpace("agent-office");
const page = task.page("p1");
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const win = await page.cdp("Browser.getWindowForTarget", {});
console.log("bounds:", JSON.stringify(win.bounds));
await page.cdp("Browser.setWindowBounds", { windowId: win.windowId, bounds: { windowState: "normal" } });

const fps = await page.evaluate(async () => {
  const vis = document.visibilityState;
  const t0 = performance.now();
  let n = 0;
  await new Promise((res) => {
    const tick = () => {
      n++;
      if (performance.now() - t0 > 1000) res();
      else requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  });
  return { vis, fps: n, err: window.__err || null };
});
console.log("fps:", JSON.stringify(fps));

try {
  const shot = await page.cdp("Page.captureScreenshot", { format: "png" }, { timeout: 20000 });
  console.log("cdp shot ok, bytes:", (shot?.data || "").length);
} catch (e) {
  console.log("cdp shot fail:", e.message);
}
