{"content": "import fs from "node:fs";

const task = await taskSpace("agent-office");
const page = task.page("p1");
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const win = await page.cdp("Browser.getWindowForTarget", {});
await page.cdp("Browser.setWindowBounds", { windowId: win.windowId, bounds: { windowState: "normal" } });

await page.goto("http://127.0.0.1:5180/");
await page.cdp("Emulation.setDeviceMetricsOverride", {
  width: 1440,
  height: 840,
  deviceScaleFactor: 1,
  mobile: false,
});
await sleep(6000);

const st = await page.evaluate(() => {
  const s = window.__office?.getState?.();
  return {
    connected: s?.connected,
    mode: s?.mode,
    agents: s?.agents.map((a) => ({ tool: a.tool, state: a.state, slot: a.slot })),
    log: s?.log.length,
    phase: s?.phase,
    tokens: s?.tokens,
  };
});
console.log("state:", JSON.stringify(st));

const dataUrl = await page.evaluate(() => {
  const c = document.querySelector("canvas");
  return c ? c.toDataURL("image/png") : null;
});
if (dataUrl) {
  const b64 = dataUrl.split(",")[1];
  fs.writeFileSync("C:/work/ego/mindforge/office-a.png", Buffer.from(b64, "base64"));
  console.log("saved bytes:", b64.length);
} else {
  console.log("no canvas");
}
