{"content": "import fs from "node:fs";

const task = await taskSpace("agent-office");
const page = task.page("p1");
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const grab = async (name) => {
  const url = await page.evaluate(() => document.querySelector("canvas").toDataURL("image/png"));
  fs.writeFileSync(`C:/work/ego/mindforge/act-${name}.png`, Buffer.from(url.split(",")[1], "base64"));
  const st = await page.evaluate(() => {
    const s = window.__office.getState();
    return {
      phase: s.phase,
      agents: s.agents.map((a) => `${a.tool}:${a.state}`),
      errors: s.errorCount,
      hudApproval: !!document.querySelector(".approval"),
      hudPhase: document.querySelector(".phase")?.textContent,
      logRows: document.querySelectorAll(".log-row").length,
    };
  });
  console.log(name, JSON.stringify(st));
};

// 造三条并行任务 + 一条失败
await page.evaluate(() => {
  const s = window.__office.getState();
  ["web_search", "pwsh", "read"].forEach((tool, i) =>
    s.apply({ type: "tool/call", seq: 9000 + i, time: Date.now(), data: { name: tool, callId: "syn-" + i } }),
  );
});
await sleep(1600);
await grab("three");

await page.evaluate(() => {
  window.__office.getState().apply({
    type: "tool/result",
    seq: 9010,
    time: Date.now(),
    data: { toolCallId: "syn-1", message: { isError: true, content: [{ type: "text", text: "Error: boom" }] } },
  });
});
await sleep(300);
await grab("kick");

await page.evaluate(() => {
  window.__office.getState().apply({
    type: "approval/asked",
    seq: 9020,
    time: Date.now(),
    data: { reason: "要升级沙箱权限才能启动预览服务器", toolName: "pwsh" },
  });
});
await sleep(2200);
await grab("approval");

// 试一次真正的整页截图（能成的话 HUD 就一起截到了）
try {
  await page.screenshot({ path: "C:/work/ego/mindforge/office-hud.png" });
  console.log("full page screenshot ok");
} catch (e) {
  console.log("full page screenshot failed:", e.message);
}
", "file_path": "C:\work\ego\mindforge\office-06.mjs"}

