{"content": "import fs from "node:fs";

const task = await taskSpace("agent-office");
const page = task.page("p1");
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const st = () =>
  page.evaluate(() => {
    const s = window.__office.getState();
    return {
      mode: s.mode,
      connected: s.connected,
      phase: s.phase,
      agents: s.agents.length,
      live: s.agents.filter((a) => a.state === "in" || a.state === "work").length,
      errors: s.errorCount,
      tools: s.toolCount,
      log: s.log.length,
      approvalBanner: !!document.querySelector(".approval"),
      hudPhase: document.querySelector(".phase")?.textContent?.trim(),
    };
  });

const grab = async (name) => {
  const url = await page.evaluate(() => document.querySelector("canvas").toDataURL("image/png"));
  fs.writeFileSync(`C:/work/ego/mindforge/fix-${name}.png`, Buffer.from(url.split(",")[1], "base64"));
};

// 重新加载，等 SSE 接上
await page.goto("http://127.0.0.1:5180/");
await page.cdp("Emulation.setDeviceMetricsOverride", {
  width: 1440,
  height: 840,
  deviceScaleFactor: 1,
  mobile: false,
});
await sleep(7000);
console.log("live:", JSON.stringify(await st()));

// 造 3 条并行 + 1 条失败（模拟真实并行）
await page.evaluate(() => {
  const s = window.__office.getState();
  ["web_search", "read", "pwsh"].forEach((tool, i) =>
    s.apply({ type: "tool/call", seq: 9000 + i, time: Date.now(), data: { name: tool, callId: "sim-" + i } }),
  );
});
await sleep(1800);
console.log("3 agents:", JSON.stringify(await st()));
await grab("three");

await page.evaluate(() => {
  window.__office.getState().apply({
    type: "tool/result",
    seq: 9010,
    time: Date.now(),
    data: { toolCallId: "sim-2", message: { isError: true, content: [{ type: "text", text: "Error: boom" }] } },
  });
});
await sleep(400);
console.log("after error:", JSON.stringify(await st()));
await grab("kick");

await page.evaluate(() => {
  window.__office.getState().apply({
    type: "approval/asked",
    seq: 9020,
    time: Date.now(),
    data: { reason: "要升级沙箱权限才能启动预览服务器", toolName: "pwsh" },
  });
});
await sleep(1500);
console.log("approval:", JSON.stringify(await st()));
await grab("approval");
