if (!records.length) return;

// 只留"有画面"的记录，并且只取最后一段 —— 一整天的工作量没法一次性演完
const VISUAL = new Set([
  "turn/start",
  "turn/end",
  "todo/write",
  "tool/call",
  "tool/result",
  "approval/asked",
  "approval/decided",
  "deliverables/presented",
]);
const picked = records.filter((r) => VISUAL.has(r.type)).slice(-120);
if (!picked.length) return;

const PACE = 420; // 每条事件之间固定停顿，忽略真实间隔

const play = () => {
  useOffice.getState().reset();
  useOffice.getState().setConnected(true);
  picked.forEach((r, i) => {
    const timer = window.setTimeout(
      // 回放时把时间改写成"刚刚"，否则会被当成历史事件跳过
      () => useOffice.getState().apply({ ...r, time: Date.now() }),
      i * PACE,
    );
    timers.push(timer);
  });
  // 播完歇一会儿再来一遍
  timers.push(window.setTimeout(play, picked.length * PACE + 9000));
};

play();

