{"content": "import fs from "node:fs";

const task = await taskSpace("agent-office");
const page = task.page("p1");
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

await page.goto("http://127.0.0.1:5180/");
await page.cdp("Emulation.setDeviceMetricsOverride", {
  width: 1440,
  height: 840,
  deviceScaleFactor: 1,
  mobile: false,
});
await sleep(12000);

const st = await page.evaluate(() => {
  const s = window.__office.getState();
  return {
    mode: s.mode,
    phase: s.phase,
    live: s.agents.filter((a) => a.state === "in" || a.state === "work").length,
    tools: s.toolCount,
    tokens: s.tokens,
    lastLog: s.log.slice(-3).map((l) => `${l.kind}:${l.text}`),
  };
});
console.log("live:", JSON.stringify(st));

const url = await page.evaluate(() => document.querySelector("canvas").toDataURL("image/png"));
fs.writeFileSync("C:/work/ego/mindforge/live-final.png", Buffer.from(url.split(",")[1], "base64"));
console.log("shot ok");
