Now write the Drama component and wire it. Let me insert before the Scene export marker.

Drama code:

```tsx
/* ---------------------------------------------------------------- 爆点 */

const KEYBOARD_POS = new THREE.Vector3(-0.15, 0.82, -1.56);
const MONITOR_POS = new THREE.Vector3(-0.15, 1.12, -2.19);
const SHARD_COUNT = 10;

function Drama() {
  const errorCount = useOffice((s) => s.errorCount);
  const deliverCount = useOffice((s) => s.deliverCount);

  const kbRef = useRef<THREE.Mesh>(null!);
  const shardRefs = useRef<(THREE.Mesh | null)[]>([]);
  const fileRef = useRef<THREE.Mesh>(null!);

  const kb = useRef({ active: false, t: 0, vel: new THREE.Vector3(), spin: new THREE.Vector3() });
  const shards = useRef(Array.from({length: SHARD_COUNT}, () => ({ p: new THREE.Vector3(), v: new THREE.Vector3(), spin: new THREE.Vector3(), r: new THREE.Euler(), life: 0 })));
  const file = useRef({ active: false, t: 0 });
  const lastErr = useRef(0);
  const lastDeliver = useRef(0);

  // 出错 → 键盘飞出去
  useEffect(() => {
    if (errorCount > lastErr.current) {
      lastErr.current = errorCount;
      kb.current.active = true;
      kb.current.t = 0;
      kb.current.vel.set(0.9 + Math.random() * 0.6, 2.8, 0.7);
      kb.current.spin.set(6, 4, 9);
      for (const s of shards.current) {
        s.p.copy(KEYBOARD_POS).add(new THREE.Vector3((Math.random()-0.5)*0.5, 0, (Math.random()-0.5)*0.2));
        s.v.set((Math.random()-0.5)*3.2, 1.6 + Math.random()*2.6, (Math.random()-0.5)*2.4);
        s.spin.set(Math.random()*10, Math.random()*10, Math.random()*10);
        s.r.set(0,0,0);
        s.life = 1.4;
      }
    }
  }, [errorCount]);

  // 交付 → 文件飞向观众
  useEffect(() => {
    if (deliverCount > lastDeliver.current) {
      lastDeliver.current = deliverCount;
      file.current.active = true;
      file.current.t = 0;
    }
  }, [deliverCount]);

  useFrame((state, dt) => {
    const d = Math.min(dt, 0.05);
    const t = state.clock.elapsedTime;

    // 键盘
    const k = kb.current;
    if (kbRef.current) {
      if (k.active) {
        k.t += d;
        if (k.t < 1.6) {
          k.vel.y -= 9.8 * d;
          kbRef.current.position.addScaledVector(k.vel, d);
          kbRef.current.rotation.x += k.spin.x * d;
          kbRef.current.rotation.y += k.spin.y * d;
          kbRef.current.rotation.z += k.spin.z * d;
          kbRef.current.visible = true;
        } else {
          kbRef.current.visible = false;
          if (k.t > 3.2) {
            // 换了个新键盘，放回桌上
            k.active = false;
            kbRef.current.position.copy(KEYBOARD_POS);
            kbRef.current.rotation.set(0,0,0);
            kbRef.current.visible = true;
          }
        }
      } else {
        kbRef.current.position.copy(KEYBOARD_POS);
        kbRef.current.visible = true;
      }
    }

    // 碎片
    for (let i = 0; i < shards.current.length; i++) {
      const s = shards.current[i];
      const m = shardRefs.current[i];
      if (!m) continue;
      if (s.life > 0) {
        s.life -= d;
        s.v.y -= 11 * d;
        s.p.addScaledVector(s.v, d);
        s.r.x += s.spin.x * d; s.r.y += s.spin.y * d; s.r.z += s.spin.z * d;
        m.position.copy(s.p);
        m.rotation.copy(s.r);
        m.visible = s.p.y > -0.1;
      } else {
        m.visible = false;
      }
    }

    // 文件飞出
    const f = file.current;
    if (fileRef.current) {
      if (f.active) {
        f.t += d;
        const p = Math.min(1, f.t / 1.4);
        fileRef.current.visible = true;
        fileRef.current.position.lerpVectors(MONITOR_POS, new THREE.Vector3(1.6, 2.4, 6.2), p);
        fileRef.current.rotation.y = p * 3;
        fileRef.current.scale.setScalar(0.5 * (1 - p * 0.4));
        if (p >= 1) { f.active = false; fileRef.current.visible = false; }
      } else {
        fileRef.current.visible = false;
      }
    }
  });

  return (
    <>
      <mesh ref={kbRef} position={KEYBOARD_POS} visible={false}>
        <boxGeometry args={[0.78, 0.05, 0.26]} />
        <meshStandardMaterial color="#20242e" />
      </mesh>
      {Array.from({ length: SHARD_COUNT }).map((_, i) => (
        <mesh key={i} ref={(el) => (shardRefs.current[i] = el)} visible={false}>
          <boxGeometry args={[0.07, 0.045, 0.07]} />
          <meshStandardMaterial color="#8b93a6" />
        </mesh>
      ))}
      <mesh ref={fileRef} visible={false}>
        <boxGeometry args={[0.34, 0.44, 0.02]} />
        <meshStandardMaterial color="#ffffff" emissive="#fff6cc" emissiveIntensity={0.6} />
      </mesh>
    </>
  );
}
```

Wait — the desk's keyboard is already rendered inside Room. If I add another keyboard at the same position that flies away, the original stays. I need to remove the static keyboard from Room, or hide it.

Simplest: remove the static keyboard from Room and let Drama own it (always visible at KEYBOARD_POS unless flying).

But Room's keyboard is a child of the desk group at local (-0.55, 0.8, 0.34) with desk at (0.4,0,-1.9) → world (-0.15, 0.8, -1.56). Yes matches.

