        fileRef.current.visible = true;
        fileRef.current.position.lerpVectors(MONITOR_POS, FLY_TO, p);
        fileRef.current.rotation.y = p * 2.6;
        fileRef.current.rotation.z = Math.sin(p * Math.PI) * 0.5;
