{"content": "import fs from "node:fs";

const task = await taskSpace("agent-office");
const page = task.page("p1");
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const grab = async (name) => {
  const url = await page.evaluate(() => document.querySelector("canvas").toDataURL("image/png"));
  fs.writeFileSync(`C:/work/ego/mindforge/v2-${name}.png`, Buffer.from(url.split(",")[1], "base64"));
  console.log("shot", name);
};

await page.goto("http://127.0.0.1:5180/");
await page.cdp("Emulation.setDeviceMetricsOverride", {
  width: 1440,
  height: 840,
  deviceScaleFactor: 1,
  mobile: false,
});
await sleep(6000);

// 出错：键盘飞出去 + 碎片 + 蓝屏 + 脸红
await page.evaluate(() => {
  const s = window.__office.getState();
  s.apply({ type: "turn/start", seq: 9500, time: Date.now(), data: { turn: 1 } });
  s.apply({ type: "tool/result", seq: 9501, time: Date.now(), data: { toolCallId: "none", message: { isError: true, content: [] } } });
});
await sleep(700);
await grab("smash-early");
await sleep(1600);
await grab("smash-mid");

// 交付：文件飞出
await page.evaluate(() => {
  window.__office.getState().apply({
    type: "deliverables/presented",
    seq: 9510,
    time: Date.now(),
    data: { files: [{ path: "a.md" }] },
  });
});
await sleep(600);
await grab("deliver");

// 审批：镜头推近 + 他走到门口
await page.evaluate(() => {
  window.__office.getState().apply({
    type: "approval/asked",
    seq: 9520,
    time: Date.now(),
    data: { reason: "要升级沙箱权限才能启动预览服务器", toolName: "pwsh" },
  });
});
await sleep(9000);
await grab("approval-close");

const st = await page.evaluate(() => {
  const s = window.__office.getState();
  return { phase: s.phase, errors: s.errorCount, deliver: s.deliverCount };
});
console.log("state:", JSON.stringify(st));
