{"command": "cd C:\work\agent-office
$p = "src\probe\model.ts"
$c = Get-Content $p -Raw -Encoding UTF8

# 1) 类型加 queued
$c = $c.Replace("  agents: AgentView[];`n  turn: number;", "  agents: AgentView[];`n  /** 同屏满了就在门外等着，里面走一个进来一个 */`n  queued: { callId: string; tool: string }[];`n  turn: number;")

# 2) 初始值 + reset
$c = $c.Replace("  agents: [],`n  turn: 0,", "  agents: [],`n  queued: [],`n  turn: 0,")
$c = $c.Replace("    set({`n      agents: [],`n      turn: 0,", "    set({`n      agents: [],`n      queued: [],`n      turn: 0,")

# 3) tool/call：满了就排队，不再踢人
$c = $c.Replace(@'
        let agents = cur.agents.filter((a) => a.callId !== callId);

        // 同屏上限：真人设 7 个
        const live = agents.filter((a) => a.state === "in" || a.state === "work");
        if (live.length >= MAX_AGENTS) {
          const oldest = live[0];
          agents = agents.map((a): AgentView =>
            a.callId === oldest.callId ? { ...a, state: "kick", endAt: now } : a,
          );
        }
'@, @'
        let agents = cur.agents.filter((a) => a.callId !== callId);

        // 同屏上限 7：满员就在门外排队，等里面走一个再进来
        const live = agents.filter((a) => a.state === "in" || a.state === "work");
        if (live.length >= MAX_AGENTS) {
          set({
            queued: [...cur.queued, { callId, tool }],
            toolCount: cur.toolCount + 1,
            phase: "working",
            lastEventAt: now,
          });
          pushLog("tool", `门外排队：${toolLabel(tool)}`);
          break;
        }
'@)

# 4) tool/result：排队中的直接撤掉
$c = $c.Replace(@'
      case "tool/result": {
        const callId = d.toolCallId || d.message?.toolCallId;
        const isError = toolResultError(d.message);
'@, @'
      case "tool/result": {
        const callId = d.toolCallId || d.message?.toolCallId;

        // 还在门外排队就结束了，直接撤掉
        const stillQueued = get().queued.find((q) => q.callId === callId);
        if (stillQueued) {
          set({ queued: get().queued.filter((q) => q.callId !== callId) });
          pushLog("result", `${toolLabel(stillQueued.tool)}：没轮上就结束了`);
          break;
        }

        const isError = toolResultError(d.message);
'@)
Set-Content -Path $p -Value $c -Encoding UTF8 -NoNewline
Select-String -Path $p -Pattern "queued" | Select-Object LineNumber,Line | Select-Object -First 10", "description": "Add queue-outside-door state"}

