{"content": "/**
 * 从 DSH 会话记录里抹掉密钥。
 *
 * 会话日志会原样保存工具调用的 arguments —— 包括你在命令行里写的
 * `$env:AHOLO_API_KEY="xxx"`、`Authorization: xxx` 之类。
 * 导出成静态文件给浏览器读之前，必须先洗一遍。
 */

const PATTERNS = [
  // 环境变量赋值：AHOLO_API_KEY=xxx / LUX3D_API_KEY: "xxx"
  /((?:AHOLO|LUX3D|OPENAI|ANTHROPIC|DEEPSEEK)_[A-Z_]*(?:KEY|TOKEN|SECRET)\s*[=:]\s*)(["']?)([A-Za-z0-9_\-]{6,})\2/gi,
  // 请求头
  /(authorization\s*[:=]\s*)(["']?)([A-Za-z0-9_\-\.]{6,})\2/gi,
  // 常见 key 前缀
  /\b(sk-[A-Za-z0-9]{12,})\b/g,
  /\b(ghp_[A-Za-z0-9]{20,})\b/g,
  /\b(xox[bap]-[A-Za-z0-9\-]{10,})\b/g,
];

export function redactString(s) {
  let out = s;
  for (const re of PATTERNS) {
    out = out.replace(re, (...m) => {
      // 有捕获组时保留前缀
      if (m.length >= 4) return `${m[1]}${m[2]}***REDACTED***${m[2]}`;
      if (m.length === 3) return `${m[1]}***REDACTED***`;
      return "***REDACTED***";
    });
  }
  return out;
}

/** 深度遍历，把所有字符串洗干净 */
export function redactRecord(rec) {
  const walk = (v) => {
    if (typeof v === "string") return redactString(v);
    if (Array.isArray(v)) return v.map(walk);
    if (v && typeof v === "object") {
      const o = {};
      for (const k of Object.keys(v)) o[k] = walk(v[k]);
      return o;
    }
    return v;
  };
  return walk(rec);
}
", "file_path": "C:\work\agent-office\scripts\redact.mjs"}

