{"command": "cd C:\work\agent-office
$p = "scripts\replay-export.mjs"
$c = Get-Content $p -Raw -Encoding UTF8
$c = $c.Replace('import { newestSessionFile, decodeFile, isShowRecord, listSessionFiles } from "./dsh-decode.mjs";', 'import { newestSessionFile, decodeFile, isShowRecord, listSessionFiles } from "./dsh-decode.mjs";
import { redactRecord } from "./redact.mjs";')
$c = $c.Replace('const all = decodeFile(target.file);
const show = all.filter(isShowRecord);', 'const all = decodeFile(target.file);
// 会话日志里有工具调用的原始参数，可能带 API key —— 落盘前先洗
const show = all.filter(isShowRecord).map(redactRecord);')
$c = $c.Replace('console.log("  文件:", target.file);', 'console.log("  文件:", target.file);
console.log("  已对工具参数做密钥脱敏");')
Set-Content -Path $p -Value $c -Encoding UTF8 -NoNewline

# tailer 也洗一遍，防止前端 devtools 里看到
$p2 = "scripts\tail-dsh.mjs"
$c2 = Get-Content $p2 -Raw -Encoding UTF8
$c2 = $c2.Replace('import {
  newestSessionFile,
  decodeFrames,
  parseLines,
  isShowRecord,
} from "./dsh-decode.mjs";', 'import {
  newestSessionFile,
  decodeFrames,
  parseLines,
  isShowRecord,
} from "./dsh-decode.mjs";
import { redactRecord } from "./redact.mjs";')
$c2 = $c2.Replace('function emit(recs) {
  for (const r of recs) if (isShowRecord(r)) pushRecord(r);
}', 'function emit(recs) {
  // 工具参数里可能出现密钥，推给浏览器之前先脱敏
  for (const r of recs) if (isShowRecord(r)) pushRecord(redactRecord(r));
}')
Set-Content -Path $p2 -Value $c2 -Encoding UTF8 -NoNewline
node -e "import('./scripts/redact.mjs').then(m=>{console.log(m.redactString('set AHOLO_API_KEY=\"***REDACTED***\" && echo'));console.log(m.redactString('Authorization: ***REDACTED***))})" 2>&1", "description": "Add redaction to export and tailer", "timeoutMs": 60000}

