{"content": "import { redactString, redactRecord } from "./redact.mjs";

const cases = [
  'set AHOLO_API_KEY="***REDACTED***" && node x',
  "AHOLO_API_KEY=***REDACTED*** node x",
  'headers: { authorization: ***REDACTED*** }',
  "Authorization: ***REDACTED***,
  "just a normal command with no secrets",
];

for (const c of cases) console.log("IN :", c, "\nOUT:", redactString(c), "\n");

const rec = {
  type: "tool/call",
  data: { name: "pwsh", arguments: JSON.stringify({ command: 'export AHOLO_API_KEY="***REDACTED***"' }) },
};
console.log("record:", JSON.stringify(redactRecord(rec)));
", "file_path": "C:\work\agent-office\scripts\_redact-test.mjs"}

